source:
\begin{explain}
We've already given examples of sets by listing their !!{element}s.
Let's discuss in more general terms how and when we can list the
!!{element}s of a set, even if that set is infinite.
\end{explain}

target:
\begin{explain}
مخکښې مو د سټونو بېلګې د هغو د \psOblique{!!{element}s} په
ليکلو ورکړې دي۔ راځئ په زياته عمومي توګه بحث وکړو چې د يوه
سټ !!{element}s څنګه او کله په لړ کښې راوړلے شو، که هغه سټ
نامتناهي هم وي۔
\end{explain}

source:
\begin{prop}
  If $A$ has an enumeration, it has an enumeration without
  repetitions.
\end{prop}

target:
\begin{prop}
  که $A$ شمېرنه ولري، بې له تکراره شمېرنه هم لري۔
\end{prop}

\begin{defn}[شمېرنه، په صوري ډول]
د سټ $A \neq \emptyset$ \emph{شمېرنه} هره !!{surjective}
تابع $f \colon \PosInt \to A$ ده۔
\end{defn}

source:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff it is empty or has an enumeration.
\end{defn}

target:
\begin{defn}
  \ollabel{defn:enumerable}
  سټ~$A$ هله او يوازې هله !!{enumerable} دے چې تش وي يا شمېرنه ولري۔
\end{defn}

source:
\begin{ex}
A function enumerating the positive integers ($\PosInt$) is simply the
identity function given by $f(n) = n$. A function enumerating the
natural numbers $\Nat$ is the function $g(n) = n - 1$.
\end{ex}

target:
\begin{ex}
د مثبتو صحيح عددونو ($\PosInt$) شمېرونکې تابع يوازې د عينيت
هغه تابع ده چې په $f(n) = n$ ورکړل شوې ده۔ د طبيعي عددونو
$\Nat$ شمېرونکې تابع $g(n) = n - 1$ ده۔
\end{ex}

source:
\begin{ex}
The functions $f\colon \PosInt \to \PosInt$ and $g \colon \PosInt \to
\PosInt$ given by
\begin{align*}
f(n) & = 2n \text{ and}\\
g(n) & = 2n - 1
\end{align*}
enumerate the even positive integers and the odd positive integers,
respectively. However, neither function is an enumeration of
$\PosInt$, since neither is !!{surjective}.
\end{ex}

target:
\begin{ex}
تابعې $f\colon \PosInt \to \PosInt$ او $g \colon \PosInt \to
\PosInt$ چې داسې ورکړل شوې دي:
\begin{align*}
f(n) & = 2n \text{ او}\\
g(n) & = 2n - 1
\end{align*}
په ترتيب سره د جفتو مثبتو صحيح عددونو او د طاقو مثبتو صحيح
عددونو شمېرنه کوي۔ خو له دوو هېڅ يوه د $\PosInt$ شمېرنه نۀ
ده، ځکه چې هېڅ يوه !!{surjective} نۀ ده۔
\end{ex}

source:
\begin{prob}
Define an enumeration of the positive squares $1$, $4$, $9$, $16$, \dots
\end{prob}

target:
\begin{prob}
د مثبتو مربع عددونو $1$، $4$، $9$، $16$، \dots يوه شمېرنه تعريف کړئ۔
\end{prob}

source:
\begin{ex}
The function $f(n) = (-1)^{n} \lceil \frac{(n-1)}{2}\rceil$ (where
$\lceil x \rceil$ denotes the \emph{ceiling} function, which rounds
$x$ up to the nearest integer) enumerates the set of
integers~$\Int$. Notice how $f$ generates the values of $\Int$ by
``hopping'' back and forth between positive and negative integers:
\[
\begin{array}{c c c c c c c c}
f(1) & f(2) & f(3) & f(4) & f(5) & f(6) & f(7) & \dots \\ \\
- \lceil \tfrac{0}{2} \rceil & \lceil \tfrac{1}{2}\rceil & - \lceil \tfrac{2}{2} \rceil & \lceil \tfrac{3}{2} \rceil & - \lceil \tfrac{4}{2} \rceil  & \lceil \tfrac{5}{2}
\rceil & - \lceil \tfrac{6}{2} \rceil & \dots \\ \\
0 & 1 & -1 & 2 & -2 & 3 & \dots
\end{array}
\]
You can also think of $f$ as defined by cases as follows:
\[
f(n) = \begin{cases}
  0 & \text{if $n = 1$}\\
  n/2 & \text{if $n$ is even}\\
  -(n-1)/2 & \text{if $n$ is odd and $>1$}
  \end{cases}
\]
\end{ex}

target:
\begin{ex}
تابع $f(n) = (-1)^{n} \lceil \frac{(n-1)}{2}\rceil$ (چې
$\lceil x \rceil$ د \emph{پاسني صحيح عدد} تابع ښيي، يعنې $x$
پورته تر ټولو نږدې صحيح عدد ته ګردوي) د صحيح عددونو~$\Int$
د سټ شمېرنه کوي۔ پام وکړئ چې $f$ د مثبتو او منفي صحيح عددونو
ترمنځ په تګ راتګ سره د $\Int$ قيمتونه څنګه راوباسي:
\[
\begin{array}{c c c c c c c c}
f(1) & f(2) & f(3) & f(4) & f(5) & f(6) & f(7) & \dots \\ \\
- \lceil \tfrac{0}{2} \rceil & \lceil \tfrac{1}{2}\rceil & - \lceil \tfrac{2}{2} \rceil & \lceil \tfrac{3}{2} \rceil & - \lceil \tfrac{4}{2} \rceil  & \lceil \tfrac{5}{2}
\rceil & - \lceil \tfrac{6}{2} \rceil & \dots \\ \\
0 & 1 & -1 & 2 & -2 & 3 & -3 & \dots
\end{array}
\]
\textbf{د ژباړې د نسخې سمون (OLSIZ-001):} د انګرېزي جدول سرليک
او د فارمول قطار f(7) لري، خو د قيمتونو قطار ئې اړين قيمت -3
پرېښے و؛ دلته د هماغه فارمول له مخې ورزيات شوے دے۔
$f$ د حالتونو له مخې داسې تعريف شوې هم ګڼلے شئ:
\[
f(n) = \begin{cases}
  0 & \text{که $n = 1$ وي}\\
  n/2 & \text{که $n$ جفت وي}\\
  -(n-1)/2 & \text{که $n$ طاق او $>1$ وي}
  \end{cases}
\]
\end{ex}

source:
\begin{prob}
  Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$. To do
  this, suppose there are !!{surjective} functions $f\colon \PosInt \to
  A$ and $g\colon \PosInt \to B$, and define !!a{surjective}
  function~$h\colon \PosInt \to A \cup B$ and prove that it is
  !!{surjective}. Also consider the cases where $A$ or~$B = \emptyset$.
\end{prob}

\begin{prob}
  Show that if $B \subseteq A$ and $A$ is !!{enumerable}, so is~$B$. To
  do this, suppose there is !!a{surjective} function $f\colon \PosInt \to
  A$. Define !!a{surjective} function~$g\colon \PosInt \to B$ and prove
  that it is !!{surjective}. What happens if $B = \emptyset$?
\end{prob}

target:
\begin{prob}
  وښيئ چې که $B \subseteq A$ او $A$ !!{enumerable} وي، نو~$B$
  هم داسې دے۔ د دې دپاره فرض کړئ چې يوه !!a{surjective}
  تابع $f\colon \PosInt \to A$ شته۔ يوه !!a{surjective}
  تابع~$g\colon \PosInt \to B$ تعريف کړئ او ثابته کړئ چې
  !!{surjective} ده۔ که $B = \emptyset$ وي، څه پېښېږي؟
\end{prob}

source:
\begin{prob}
  Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
  !!{enumerable}, so is $A_1 \cup \dots \cup A_n$. You may assume the
  fact that if two sets $A$ and~$B$ are !!{enumerable}, so is~$A \cup
  B$. 
\end{prob}

target:
\begin{prob}
  پر $n$ د استقرا په وسيله وښيئ چې که $A_1$، $A_2$، \dots،
  $A_n$ ټول !!{enumerable} وي، نو $A_1 \cup \dots \cup A_n$
  هم داسې دے۔ دا حقيقت فرضولے شئ چې که دوه سټونه $A$ او~$B$
  !!{enumerable} وي، نو~$A \cup B$ هم داسې دے۔
\end{prob}

source:
\begin{prop}\ollabel{prop:enum-shift}
  There is !!a{surjection} $f\colon \PosInt \to A$ iff there is
  !!a{surjection} $g\colon \Nat \to A$.
\end{prop}

target:
\begin{prop}\ollabel{prop:enum-shift}
  يوه !!a{surjection} $f\colon \PosInt \to A$ هله او يوازې هله
  شته چې يوه !!a{surjection} $g\colon \Nat \to A$ شته وي۔
\end{prop}

source:
\begin{proof}
  Given !!a{surjection} $f\colon \PosInt \to A$, we can define $g(n) =
  f(n+1)$ for all $n \in \Nat$. It is easy to see that $g\colon \Nat
  \to A$ is !!{surjective}. Conversely, given !!a{surjection} $g\colon
  \Nat \to A$, define $f(n) = g(n-1)$.
\end{proof}

\begin{cor}\ollabel{cor:enum-nat}
A set $A$ is !!{enumerable} iff it is empty or there is
!!a{surjective} function $f\colon \Nat \to A$.
\end{cor}

target:
\begin{cor}\ollabel{cor:enum-nat}
سټ $A$ هله او يوازې هله !!{enumerable} دے چې تش وي يا يوه
!!a{surjective} تابع $f\colon \Nat \to A$ شته وي۔
\end{cor}

source:
\begin{prop}\ollabel{prop:enum-bij}
If $f\colon \PosInt \to A$ is !!{surjective} (i.e., an enumeration
of~$A$), there is !!a{bijection} $g\colon Z \to A$ where $Z$ is
either~$\PosInt$ or $\{1, \dots, n\}$ for some~$n \in \PosInt$.
\end{prop}

target:
\begin{prop}\ollabel{prop:enum-bij}
که $f\colon \PosInt \to A$ يوه !!{surjective} تابع وي (يعنې
د~$A$ شمېرنه وي)، نو يوه !!a{bijection} $g\colon Z \to A$
شته چې $Z$ يا~$\PosInt$ وي يا د کوم~$n \in \PosInt$ دپاره
$\{1, \dots, n\}$ وي۔
\end{prop}

source:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

target:
\begin{cor}\ollabel{cor:enum-nat-bij}
سټ $A$ هله او يوازې هله !!{enumerable} دے چې تش وي يا يوه
!!a{bijection} $f\colon N \to A$ شته وي، چې يا $N = \Nat$
وي يا د کوم $n \in \Nat$ دپاره $N = \{0, \dots, n\}$ وي۔
\end{cor}

source:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

\begin{prob}
  According to \olref[sfr][siz][enm]{defn:enumerable}, a set $A$ is
  enumerable iff $A = \emptyset$ or there is !!a{surjective} $f\colon
  \PosInt \to A$.  It is also possible to define ``!!{enumerable} set''
  precisely by: a set is enumerable iff there is !!a{injective}
  function $g\colon A \to \PosInt$.  Show that the definitions are
  equivalent, i.e., show that there is !!a{injective} function
  $g\colon A \to \PosInt$ iff either $A = \emptyset$ or there is
  !!a{surjective} $f\colon \PosInt \to A$.
\end{prob}

target:
\begin{prob}
  د \olref[sfr][siz][enm]{defn:enumerable} له مخې، سټ $A$ هله
  او يوازې هله د شمېر وړ دے چې $A = \emptyset$ وي يا يوه
  !!a{surjective} $f\colon \PosInt \to A$ شته وي۔ «!!{enumerable}
  سټ» په کره ډول داسې هم تعريفولے شو: سټ هله او يوازې هله
  د شمېر وړ دے چې يوه !!a{injective} تابع $g\colon A \to \PosInt$
  شته وي۔ وښيئ چې تعريفونه همارزښته دي؛ يعنې وښيئ چې يوه
  !!a{injective} تابع $g\colon A \to \PosInt$ هله او يوازې هله
  شته چې يا $A = \emptyset$ وي يا يوه !!a{surjective}
  $f\colon \PosInt \to A$ شته وي۔
\end{prob}

source:
\begin{prop}\ollabel{natsquaredenumerable}
$\Nat \times \Nat$ is !!{enumerable}.
\end{prop}

target:
\begin{prop}\ollabel{natsquaredenumerable}
$\Nat \times \Nat$ يو !!{enumerable} سټ دے۔
\end{prop}

source:
\begin{proof}
Let $f \colon \Nat \to \Nat\times\Nat$ take each $k \in \Nat$ to the
tuple $\tuple{n,m} \in \Nat \times \Nat$ such that $k$ is the value of
the $n$th row and $m$th column in Cantor's zig-zag array. 
\end{proof}

target:
\begin{proof}
فرض کړئ $f \colon \Nat \to \Nat\times\Nat$ هر $k \in \Nat$
له هغې مرتبې څوګونې $\tuple{n,m} \in \Nat \times \Nat$ سره
تړي چې $k$ د کانتور د زيګزاګ په جدول کښې د $n$م قطار او
$m$م ستون قيمت وي۔
\end{proof}

source:
\begin{prop}
$\Nat^n$ is !!{enumerable}, for every $n \in \Nat$.
\end{prop}

target:
\begin{prop}
د هر $n \in \Nat$ دپاره، $\Nat^n$ يو !!{enumerable} سټ دے۔
\end{prop}

source:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-n}
Show that $(\PosInt)^n$ is !!{enumerable}, for every $n \in \Nat$.
\end{prob}

target:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-n}
وښيئ چې د هر $n \in \Nat$ دپاره، $(\PosInt)^n$ يو !!{enumerable} سټ دے۔
\end{prob}

source:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-star}
  Show that $(\PosInt)^*$ is !!{enumerable}. You may assume \cref{sfr:siz:zigzag:prob:posint-n}.
\end{prob}

target:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-star}
  وښيئ چې $(\PosInt)^*$ يو !!{enumerable} سټ دے۔
  \cref{sfr:siz:zigzag:prob:posint-n} فرضولے شئ۔
\end{prob}

source:
This function $g$ is the \emph{inverse} of an enumeration of a set of
pairs. Such functions are called \emph{pairing functions}.
\end{explain}

target:
دا تابع $g$ د جوړو د يوه سټ د شمېرنې \emph{معکوس} ده۔ داسې
تابعې \emph{جوړوونکې تابعې} بلل کېږي۔
\end{explain}

source:
\begin{explain}
We can use pairing functions to encode, e.g., pairs of natural numbers;
or, in other words, we can represent each \emph{pair} of elements
using a \emph{single} number. Using the inverse of the pairing
function, we can \emph{decode} the number, i.e., find out which
pair it represents.
\end{explain}

target:
\begin{explain}
جوړوونکې تابعې د بېلګې په توګه د طبيعي عددونو د جوړو د
کوډولو دپاره کارولے شو؛ يا په بله وينا، د غړو هره \emph{جوړه}
په يوه \emph{واحد} عدد ښودلے شو۔ د جوړوونکې تابعې په معکوس
عدد بېرته لوستلے شو؛ يعنې معلومولے شو چې کومه جوړه ښيي۔
\end{explain}

source:
\begin{prob}
Give an enumeration of the set of all non-negative rational numbers. 
\end{prob}

target:
\begin{prob}
د ټولو غير منفي ناطقو عددونو د سټ يوه شمېرنه ورکړئ۔
\end{prob}

source:
\begin{prob}
Show that $\Rat$ is !!{enumerable}. Recall that any rational number 
can be written as a fraction $z/m$ with $z \in \Int$, $m \in \Nat^+$.
\end{prob}

target:
\begin{prob}
وښيئ چې $\Rat$ !!{enumerable} دے۔ په ياد ولرئ چې هر ناطق عدد
د کسر $z/m$ په توګه ليکل کېدے شي، چې $z \in \Int$ او
$m \in \Nat^+$ وي۔
\end{prob}

source:
\begin{prob}
Define an enumeration of $\Bin^*$.
\end{prob}

target:
\begin{prob}
د $\Bin^*$ يوه شمېرنه تعريف کړئ۔
\end{prob}

source:
\begin{prob}
Recall from your introductory logic course that each possible truth
table expresses a truth function. In other words, the truth functions
are all functions from $\Bin^k \to \Bin$ for some~$k$. Prove that the
set of all truth functions is enumerable.
\end{prob}

target:
\begin{prob}
د منطق له پېژندنيز کورسه په ياد ولرئ چې د رښتياوالي هر ممکن
جدول د رښتياوالي يوه تابع څرګندوي۔ په بله وينا، د کوم~$k$
دپاره د رښتياوالي تابعې ټولې تابعې له $\Bin^k \to \Bin$ څخه
دي۔ ثابته کړئ چې د رښتياوالي د ټولو تابعو سټ د شمېر وړ دے۔
\end{prob}

source:
\begin{prob}
Show that the set of all finite subsets of an arbitrary infinite
!!{enumerable} set is !!{enumerable}.
\end{prob}

target:
\begin{prob}
وښيئ چې د يوه خپل سري نامتناهي !!{enumerable} سټ د ټولو
متناهي فرعي سټونو سټ !!{enumerable} دے۔
\end{prob}

source:
\begin{prob}
Show that the !!{enumerable} union of !!{enumerable} sets is
!!{enumerable}. That is, whenever $A_1$, $A_2$, \dots{} are sets, and
each $A_i$ is !!{enumerable}, then the union $\bigcup_{i=1}^\infty
A_i$ of all of them is also !!{enumerable}. [NB: this is hard!]
\end{prob}

\begin{prob}
Let $f \colon A \times B \to \Nat$ be an arbitrary pairing function.
Show that the inverse of $f$ is an enumeration of $A \times B$.
\end{prob}

\begin{prob}
Specify a function that encodes $\Nat^3$.
\end{prob}

target:
\begin{prob}
داسې تابع وټاکئ چې $\Nat^3$ کوډ کړي۔
\end{prob}

source:
\begin{explain}
Accordingly, in our second enumeration of $\Nat^2$, the pair
$\tuple{0,0}$ has code $h(0,0) = 2^0(2\cdot 0+1) - 1 = 0$;
$\tuple{1,2}$ has code $2^{1} \cdot (2 \cdot 2 + 1) - 1 = 2
\cdot 5 - 1 = 9$; $\tuple{2,6}$ has code $2^{2} \cdot (2
\cdot 6 + 1) - 1 = 51$.
\end{explain}

\begin{editorial}
  This section proves the non-enumerability of $\Bin^\omega$ and
  $\Pow{\PosInt}$ using the definition in \olref[enm]{sec}. It is
  designed to be a little more elementary and a little more detailed
  than the version in \olref[enm-alt]{sec}
\end{editorial}

target:
\begin{editorial}
  دا برخه په \olref[enm]{sec} کښې د ورکړل شوي تعريف په کارولو د
  $\Bin^\omega$ او $\Pow{\PosInt}$ د شمېر نۀ وړ والے ثابتوي۔ دا
  د \olref[enm-alt]{sec} له بڼې څخه لږه ابتدايي او لږه زياته
  تفصيلي جوړه شوې ده۔
\end{editorial}

تر هر څه لومړے ښايي همدا خبره لا حيرانوونکې وي چې !!{nonenumerable}
سټونه شته۔ د هر !!{enumerable} سټ~$A$ دپاره يوه !!a{surjective}
تابع $f \colon \PosInt \to A$ شته۔ که يو سټ !!{nonenumerable} وي،
داسې تابع نۀ شته۔ يعنې هېڅ هغه تابع چې د~$\PosInt$ بې‌شمېره
!!{element}s پر~$A$ نقشوي، ټول~$A$ نۀ شي پوره کولے۔ نو په~$A$
کښې د بې‌شمېره مثبتو صحيح عددونو په پرتله «زيات» !!{element}s شته۔

source:
\begin{thm}
