\begin{prob}
Consider adding to $\Lang{L_0}$ a ternary connective $\diamondsuit$
with evaluation given by
\begin{gather*}
  \pValue{v}(\diamondsuit( !A , !B , !C ) ) = \begin{cases}
    \pValue{v}( !B ) &
    \text{if $\pValue{v}(!A) = \True$;}\\
    \pValue{v}( !C ) &
    \text{if $\pValue{v}(!A) = \False $}.
  \end{cases}
\end{gather*}
Write down the truth table for this connective.
\end{prob}

target:
\begin{prob}
فرض کړئ چې $\Lang{L_0}$ ته يو درې ځايه نښلوونکے $\diamondsuit$
ورزياتوو چې ارزونه ئې داسې ورکول شوې ده:
\begin{gather*}
  \pValue{v}(\diamondsuit( !A , !B , !C ) ) = \begin{cases}
    \pValue{v}( !B ) &
    \text{که $\pValue{v}(!A) = \True$ وي؛}\\
    \pValue{v}( !C ) &
    \text{که $\pValue{v}(!A) = \False $ وي}۔
  \end{cases}
\end{gather*}
د دې نښلوونکي د رښتياوالي جدول وليکئ۔
\end{prob}

