source:
\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target:
\begin{prop}[متناهي شاهد]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item که $\Gamma \Proves !A$ وي، نو يو متناهي فرعي سټ
    $\Gamma_0 \subseteq \Gamma$ شته چې $\Gamma_0 \Proves !A$۔
  \item که د~$\Gamma$ هر متناهي فرعي سټ سازګار وي، نو $\Gamma$
    سازګار دے۔
  \end{enumerate}
\end{prop}

source:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite subset
      $\Gamma_0 \subseteq \Gamma$ such that the sequent $\Gamma_0
      \Sequent !A$ has !!a{derivation}. Consequently, $\Gamma_0
      \Proves !A$.
    \item If $\Gamma$ is inconsistent, there is a finite
      subset~$\Gamma_0 \subseteq \Gamma$ such that $\Log{LK}$
      !!{derive}s $\Gamma_0 \Sequent \quad$. But then $\Gamma_0$ is a
      finite subset of~$\Gamma$ that is inconsistent.
  \end{enumerate}
\end{proof}

target:
\begin{proof}
  \begin{enumerate}
    \item که $\Gamma \Proves !A$ وي، نو يو متناهي فرعي سټ
      $\Gamma_0 \subseteq \Gamma$ شته، داسې چې د
      $\Gamma_0 \Sequent !A$ سېکوېنټ !!a{derivation} لري۔ له دې امله
      $\Gamma_0 \Proves !A$۔
    \item که $\Gamma$ ناسازګار وي، نو يو متناهي فرعي سټ
      $\Gamma_0 \subseteq \Gamma$ شته، داسې چې $\Log{LK}$ د
      $\Gamma_0 \Sequent \quad$ سېکوېنټ !!{derive}s کړي۔ خو بيا
      $\Gamma_0$ د~$\Gamma$ يو ناسازګار متناهي فرعي سټ دے۔
  \end{enumerate}
\end{proof}

