source:
\begin{prop}\ollabel{prop:explicit-inc}
  If $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$, then $\Gamma$ is
  inconsistent.
\end{prop}

target:
\begin{prop}\ollabel{prop:explicit-inc}
  که $\Gamma \Proves !A$ او $\lnot !A \in \Gamma$ وي، نو $\Gamma$
  ناسازګار دے۔
\end{prop}

source:
\begin{proof}
  Suppose $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$.  Then there
  is !!a{derivation}~$\pi$ of a sequent $\Gamma_0 \Sequent !A$. The
  sequent $\lnot !A, \Gamma_0 \Sequent \quad$ is also !!{derivable}:
  \begin{prooftree}
    \AxiomC{}
    \RightLabel{$\pi$}
    \Deduce$\Gamma_0 \fCenter !A$
    \Axiom$!A \fCenter !A$
    \RightLabel{\LeftR{\lnot}}
    \UnaryInf$\lnot !A, !A \fCenter$
    \RightLabel{\LeftR{\Exchange}}
    \UnaryInf$!A, \lnot !A \fCenter$
    \RightLabel{\Cut}
    \BinaryInf$\Gamma_0, \lnot !A \fCenter$
  \end{prooftree}
  Since $\lnot !A \in \Gamma$ and $\Gamma_0 \subseteq \Gamma$, this
  shows that $\Gamma$ is inconsistent.
\end{proof}

target:
\begin{proof}
  فرض کړئ $\Gamma \Proves !A$ او $\lnot !A \in \Gamma$۔ بيا د کوم
  سېکوېنټ $\Gamma_0 \Sequent !A$ !!a{derivation}~$\pi$ شته۔
  سېکوېنټ $\lnot !A, \Gamma_0 \Sequent \quad$ هم !!{derivable} دے:
  \begin{prooftree}
    \AxiomC{}
    \RightLabel{$\pi$}
    \Deduce$\Gamma_0 \fCenter !A$
    \Axiom$!A \fCenter !A$
    \RightLabel{\LeftR{\lnot}}
    \UnaryInf$\lnot !A, !A \fCenter$
    \RightLabel{\LeftR{\Exchange}}
    \UnaryInf$!A, \lnot !A \fCenter$
    \RightLabel{\Cut}
    \BinaryInf$\Gamma_0, \lnot !A \fCenter$
  \end{prooftree}
  ځکه چې $\lnot !A \in \Gamma$ او $\Gamma_0 \subseteq \Gamma$،
  نو دا ښيي چې $\Gamma$ ناسازګار دے۔
\end{proof}

source:
\begin{prop}\ollabel{prop:provability-exhaustive}
  If $\Gamma \cup \{!A\}$ and $\Gamma \cup \{\lnot !A\}$ are both
  inconsistent, then $\Gamma$ is inconsistent.
\end{prop}

target:
\begin{prop}\ollabel{prop:provability-exhaustive}
  که $\Gamma \cup \{!A\}$ او $\Gamma \cup \{\lnot !A\}$ دواړه
  ناسازګار وي، نو $\Gamma$ ناسازګار دے۔
\end{prop}

source:
\begin{proof}
There are finite sets $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1
\subseteq \Gamma$ and $\Log{LK}$-!!{derivation}s $\pi_0$ and $\pi_1$
of $!A, \Gamma_0 \Sequent \quad$ and $\lnot !A, \Gamma_1 \Sequent
\quad$, respectively. We can then !!{derive}
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ !A, \Gamma_0 \fCenter $
\RightLabel{\RightR{\lnot}}
\UnaryInf$ \Gamma_0 \fCenter \lnot !A$
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\lnot !A, \Gamma_1 \fCenter  $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0, \Gamma_1 \fCenter $
\end{prooftree}
Since $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$. Hence $\Gamma$ is
inconsistent.
\end{proof}

target:
\begin{proof}
داسې متناهي سټونه $\Gamma_0 \subseteq \Gamma$ او
$\Gamma_1 \subseteq \Gamma$ او داسې
$\Log{LK}$-!!{derivation}s $\pi_0$ او $\pi_1$ شته چې په همدې ترتيب
د $!A, \Gamma_0 \Sequent \quad$ او
$\lnot !A, \Gamma_1 \Sequent \quad$ اشتقاقونه دي۔ بيا لاندې
!!{derive} کولے شو:
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ !A, \Gamma_0 \fCenter $
\RightLabel{\RightR{\lnot}}
\UnaryInf$ \Gamma_0 \fCenter \lnot !A$
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\lnot !A, \Gamma_1 \fCenter  $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0, \Gamma_1 \fCenter $
\end{prooftree}
ځکه چې $\Gamma_0 \subseteq \Gamma$ او $\Gamma_1 \subseteq \Gamma$،
نو $\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$۔ له دې امله $\Gamma$
ناسازګار دے۔
\end{proof}

