\begin{prop}\ollabel{prop:provability-land}
  \begin{enumerate}
  \item \ollabel{prop:provability-land-left} Both $!A \land !B \Proves
    !A$ and $!A \land !B \Proves !B$.
  \item \ollabel{prop:provability-land-right} $!A, !B \Proves !A \land
    !B$.
  \end{enumerate}
\end{prop}

target:
\begin{prop}\ollabel{prop:provability-land}
  \begin{enumerate}
  \item \ollabel{prop:provability-land-left} هم
    $!A \land !B \Proves !A$ او هم
    $!A \land !B \Proves !B$۔
  \item \ollabel{prop:provability-land-right}
    $!A, !B \Proves !A \land !B$۔
  \end{enumerate}
\end{prop}

source:
\begin{proof}
  \begin{enumerate}
  \item Both sequents $!A \land !B \Sequent !A$ and $!A \land !B \Sequent
    !B$ are !!{derivable}:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !A$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !B$
    \end{prooftree}
    \item Here is !!a{derivation} of the sequent $!A, !B \Sequent !A \land !B$:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\land}}
      \BinaryInf$!A, !B \fCenter !A \land !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

target:
\begin{proof}
  \begin{enumerate}
  \item دواړه سېکوېنټونه $!A \land !B \Sequent !A$ او
    $!A \land !B \Sequent !B$ !!{derivable} دي:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !A$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\land}}
      \UnaryInf$!A \land !B \fCenter !B$
    \end{prooftree}
    \item دا د سېکوېنټ $!A, !B \Sequent !A \land !B$ يو
    !!a{derivation} دے۔
    \textbf{د ژباړې د نسخې سمون (OLSQ-004):} د سرچينې په ونه کښې
    د عطف-ښۍ قاعدې دواړو مقدمو يو شان مقدم نۀ درلود؛ دلته د
    جوړښتي استنتاجونو دوه ګونې کرښې دواړه مقدمې له پايلې سره سموي۔
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \doubleLine
      \UnaryInf$!A, !B \fCenter !A$
      \Axiom$!B \fCenter !B$
      \doubleLine
      \UnaryInf$!A, !B \fCenter !B$
      \RightLabel{\RightR{\land}}
      \BinaryInf$!A, !B \fCenter !A \land !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

