source:
\begin{editorial}
This section collects the definitions the provability relation
and consistency for natural deduction.
\end{editorial}

target:
\begin{editorial}
دا برخه د فطري استنتاج د اثبات‌پذيرۍ اړيکې او سازګارۍ تعريفونه
راټولوي۔
\end{editorial}

\begin{explain}
لکه څنګه چې مو يو شمېر مهم معنايي مفاهيم (اعتبار، معنايي استلزام،
د صدق وړتيا) تعريف کړل، اوس ورسره سم \emph{ثبوت-تيوريکي مفاهيم}
تعريفوو۔ دا مفاهيم په !!{structure}s کښې د !!{sentence}s د پوره
کېدو له لارې نۀ، بلکې له نورو څخه د ځينو !!{sentence}s د
!!{derivability} يا !!{nonderivability} له لارې تعريفېږي۔ دا مهمه
موندنه وه چې دغه مفاهيم سره سمون خوري۔ د دې سمون منځپانګه د
\emph{سموالي} او \emph{بشپړتيا قضيې} دي۔
\end{explain}

source:
\begin{defn}[Theorems]
A !!{sentence}~$!A$ is a \emph{theorem} if there is !!a{derivation}
of~$!A$ in natural deduction in which all assumptions are
!!{discharged}.  We write $\Proves !A$ if $!A$ is a theorem and
$\Proves/ !A$ if it is not.
\end{defn}

target:
\begin{defn}[قضيې]
يوه !!{sentence}~$!A$ هله \emph{قضيه} ده چې په فطري استنتاج کښې
د~$!A$ داسې !!a{derivation} وي چې ټولې فرضيې پکې !!{discharged}
شوې وي۔ که $!A$ قضيه وي، $\Proves !A$ ليکو، او که نۀ وي
$\Proves/ !A$ ليکو۔
\end{defn}

\begin{defn}[سازګاري]
د !!{sentence}s يو سټ~$\Gamma$ هله او يوازې هله \emph{ناسازګار}
دے چې $\Gamma \Proves \lfalse$ وي۔ که $\Gamma$ ناسازګار نۀ وي،
يعنې $\Gamma \Proves/ \lfalse$ وي، نو \emph{سازګار} ئې بولو۔
\end{defn}

source:
\begin{prop}[Reflexivity]
\ollabel{prop:reflexivity}
If $!A \in \Gamma$, then $\Gamma \Proves !A$.
\end{prop}

target:
\begin{prop}[انعکاسيت]
\ollabel{prop:reflexivity}
که $!A \in \Gamma$ وي، نو $\Gamma \Proves !A$۔
\end{prop}

source:
\begin{proof}
The assumption $!A$ by itself is !!a{derivation} of~$!A$ where every
!!{undischarged} assumption (i.e., $!A$) is in~$\Gamma$.
\end{proof}

target:
\begin{proof}
فرضيه~$!A$ په يوازې ځان د~$!A$ داسې !!a{derivation} دے چې هره
!!{undischarged} فرضيه ئې (يعنې $!A$) په~$\Gamma$ کښې ده۔
\end{proof}

source:
\begin{prop}[Monotonicity]
\ollabel{prop:monotonicity}
If $\Gamma \subseteq \Delta$ and $\Gamma \Proves !A$, then $\Delta
\Proves !A$.
\end{prop}

target:
\begin{prop}[يکنواختي]
\ollabel{prop:monotonicity}
که $\Gamma \subseteq \Delta$ او $\Gamma \Proves !A$ وي، نو
$\Delta \Proves !A$۔
\end{prop}

source:
\begin{proof}
Any !!{derivation} of $!A$ from $\Gamma$ is also !!a{derivation} of
$!A$ from~$\Delta$.
\end{proof}

target:
\begin{proof}
له~$\Gamma$ څخه د~$!A$ هر !!{derivation} له~$\Delta$ څخه هم د~$!A$
!!a{derivation} دے۔
\end{proof}

source:
\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup \Delta \Proves
!B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

target:
\begin{prop}[انتقاليت]
\ollabel{prop:transitivity}
که $\Gamma \Proves !A$ او $\{!A\} \cup \Delta \Proves !B$ وي، نو
$\Gamma \cup \Delta \Proves !B$۔
\end{prop}

source:
\begin{proof}
If $\Gamma \Proves !A$, there is !!a{derivation}~$\delta_0$ of~$!A$
with all !!{undischarged} assumptions in~$\Gamma$.  If $\{!A\} \cup
\Delta \Proves !B$, then there is !!a{derivation}~$\delta_1$ of~$!B$
with all !!{undischarged} assumptions in~$\{!A\} \cup \Delta$.
Now consider:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
The !!{undischarged} assumptions are now all among $\Gamma \cup
\Delta$, so this shows $\Gamma \cup \Delta \Proves !B$.
\end{proof}

target:
\begin{proof}
که $\Gamma \Proves !A$ وي، د~$!A$ داسې !!a{derivation}~$\delta_0$
شته چې ټولې !!{undischarged} فرضيې ئې په~$\Gamma$ کښې دي۔ که
$\{!A\} \cup \Delta \Proves !B$ وي، د~$!B$ داسې
!!a{derivation}~$\delta_1$ شته چې ټولې !!{undischarged} فرضيې ئې
په~$\{!A\} \cup \Delta$ کښې دي۔ اوس لاندې وګورئ:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
اوس ټولې !!{undischarged} فرضيې په~$\Gamma \cup \Delta$ کښې دي؛
نو دا $\Gamma \cup \Delta \Proves !B$ ښيي۔
\end{proof}

