\begin{prop}
\ollabel{prop:incons}
The following are equivalent. 
    \begin{enumerate}
      \item \( \Gamma \) is inconsistent.
      \item \( \Gamma \Proves {!A} \) for every !!{sentence}~\( {!A} \).
      \item \( \Gamma \Proves {!A} \) and \( \Gamma \Proves \lnot {!A} \) for some !!{sentence}~\( {!A} \).
    \end{enumerate}
\end{prop}

target:
\begin{prop}
\ollabel{prop:incons}
لاندې شرطونه معادل دي۔
    \begin{enumerate}
      \item \( \Gamma \) ناسازګار دے۔
      \item د هرې !!{sentence}~\( {!A} \) دپاره \( \Gamma \Proves {!A} \)۔
      \item د کومې !!{sentence}~\( {!A} \) دپاره \( \Gamma \Proves {!A} \) او \( \Gamma \Proves \lnot {!A} \)۔
    \end{enumerate}
\end{prop}

