  \begin{enumerate}
  \item $\{!A \lor !B, \lnot !A, \lnot !B\}$ ناسازګار دے۔
  \item دواړه $!A \Proves !A \lor !B$ او
    $!B \Proves !A \lor !B$۔
  \end{enumerate}
