\begin{defn}
  If $s$ is !!a{variable} assignment for !!a{structure}~$\Struct M$
  and $m \in \Domain{M}$, then the assignment~$\Subst{s}{m}{x}$ is the
  variable assignment defined by
  \[\Subst{s}{m}{x}(y) = \begin{cases}
    m & \text{if } y \ident x\\
    s(y) & \text{otherwise}.
  \end{cases}\]
\end{defn}

