\begin{defn}
\ollabel{defn:reduct}
Suppose $\Lang L \subseteq \Lang L'$, $\Struct M$ is an
$\Lang L$-!!{structure} and $\Struct M'$ is an $\Lang L'$-!!{structure}.
$\Struct M$ is the \emph{reduct} of $\Struct M'$ to $\Lang L$, and
$\Struct M'$ is an \emph{expansion} of $\Struct M$ to $\Lang L'$ iff
\begin{enumerate}
\item $\Domain{M} = \Domain{M'}$
\item For every !!{constant}~$c \in \Lang L$, $\Assign{c}{M} =
  \Assign{c}{M'}$.
\item For every !!{function}~$f \in \Lang L$, $\Assign{f}{M} =
  \Assign{f}{M'}$.
\item For every !!{predicate}~$P \in \Lang L$, $\Assign{P}{M} =
  \Assign{P}{M'}$.
\end{enumerate}
\end{defn}

target:
\begin{defn}
\ollabel{defn:reduct}
فرض کړئ $\Lang L \subseteq \Lang L'$، $\Struct M$ يو
$\Lang L$-!!{structure} او $\Struct M'$ يو $\Lang L'$-!!{structure}
دے۔ $\Struct M$ د~$\Struct M'$ تر~$\Lang L$ پورې \emph{راکمونه}، او
$\Struct M'$ د~$\Struct M$ تر~$\Lang L'$ پورې \emph{غځونه} هله او
يوازې هله ده چې
\begin{enumerate}
\item $\Domain{M} = \Domain{M'}$
\item د هر داسې !!{constant}~$c \in \Lang L$ دپاره،
  $\Assign{c}{M} = \Assign{c}{M'}$ وي۔
\item د هر داسې !!{function}~$f \in \Lang L$ دپاره،
  $\Assign{f}{M} = \Assign{f}{M'}$ وي۔
\item د هر داسې !!{predicate}~$P \in \Lang L$ دپاره،
  $\Assign{P}{M} = \Assign{P}{M'}$ وي۔
\end{enumerate}
\end{defn}

