source:
\begin{defn}
A !!{structure} for $\Lang{L_A}$ is \emph{standard} if it is
isomorphic to~$\Struct{N}$.
\end{defn}

target:
\begin{defn}
د~$\Lang{L_A}$ يو !!{structure} \emph{معياري} دے، که له~$\Struct{N}$
سره آيزومورف وي۔
\end{defn}

source:
\begin{prop}
\ollabel{prop:standard-domain} If !!a{structure}~$\Struct{M}$ is standard,
then its domain is the set of values of the standard numerals, i.e.,
\[
\Domain{M} = \Setabs{\Value{\num{n}}{M}}{n \in \Nat}
\]
\end{prop}

target:
\begin{prop}
\ollabel{prop:standard-domain} که !!a{structure}~$\Struct{M}$ معياري
وي، نو تعريف ساحه ئې د معياري عددنښو د ارزښتونو سټ دے، يعنې:
\[
\Domain{M} = \Setabs{\Value{\num{n}}{M}}{n \in \Nat}
\]
\end{prop}

\begin{explain}
که د~$\Lang{L_A}$ يو جوړښت~$\Struct{M}$ معياري وي، د~!!{domain}
ټول غړي ئې د معياري عددنښو $\num{0}$، $\num{1}$، $\num{2}$،
\dots په نوم يادېدے شي، يعنې د $\Obj{0}$، $\Obj{0}'$،
$\Obj{0}''$ او داسې نورو ترمونو په وسيله۔ البته دا معنا نۀ لري چې د
$\Domain{M}$ !!{element}s پخپله شمېرې دي؛ يوازې دومره ده چې د هغو
په نښه کولے شو، لکه څنګه چې په~$\Domain{N}$ کښې شمېرې نښه کوو۔
\end{explain}

source:
\begin{prob}
Show that the converse of \olref[mod][mar][stm]{prop:standard-domain}
is false, i.e., give an example of !!a{structure}~$\Struct{M}$ with
$\Domain{M} = \Setabs{\Value{\num{n}}{M}}{n \in \Nat}$ that is not
isomorphic to~$\Struct{N}$.
\end{prob}

target:
\begin{prob}
وښيئ چې د~\olref[mod][mar][stm]{prop:standard-domain} معکوس ناسم دے؛
يعنې داسې يو !!a{structure}~$\Struct{M}$ ورکړئ چې
$\Domain{M} = \Setabs{\Value{\num{n}}{M}}{n \in \Nat}$ وي، خو له
$\Struct{N}$ سره آيزومورف نۀ وي۔
\end{prob}

source:
\begin{prop}
\ollabel{prop:thq-standard}
If $\Sat{M}{\Th{Q}}$, and $\Domain{M} = \Setabs{\Value{\num{n}}{M}}{n
  \in \Nat}$, then $\Struct{M}$ is standard.
\end{prop}

target:
\begin{prop}
\ollabel{prop:thq-standard}
که $\Sat{M}{\Th{Q}}$ او $\Domain{M} =
\Setabs{\Value{\num{n}}{M}}{n \in \Nat}$ وي، نو $\Struct{M}$ معياري دے۔
\end{prop}

source:
\begin{prop}
\ollabel{prop:thq-unique-iso} If $\Struct{M}$ is standard, then $g$ from
the proof of \olref{prop:thq-standard} is the only isomorphism from $\Struct{N}$ to~$\Struct{M}$.
\end{prop}

target:
\begin{prop}
\ollabel{prop:thq-unique-iso} که $\Struct{M}$ معياري وي، نو د
\olref{prop:thq-standard} له ثبوت څخه $g$ له~$\Struct{N}$ څخه
$\Struct{M}$ ته يوازينے آيزومورفيزم دے۔
\end{prop}

source:
\begin{explain}
We call !!a{structure} for $\Lang{L_A}$ standard if it is isomorphic
to~$\Struct{N}$. If !!a{structure} isn't isomorphic to~$\Struct{N}$,
it is called non-standard.
\end{explain}

target:
\begin{explain}
د~$\Lang{L_A}$ يو !!a{structure} هغه وخت معياري بولو چې له
$\Struct{N}$ سره آيزومورف وي۔ که يو !!a{structure} له~$\Struct{N}$
سره آيزومورف نۀ وي، نامعياري بلل کېږي۔
\end{explain}

source:
\begin{defn}
A !!{structure}~$\Struct{M}$ for $\Lang{L_A}$ is \emph{non-standard}
if it is not isomorphic to~$\Struct{N}$. The !!{element}s $x \in
\Domain{M}$ which are equal to $\Value{\num{n}}{M}$ for some $n \in
\Nat$ are called \emph{standard numbers} (of $\Struct{M}$), and those
not, \emph{non-standard numbers}.
\end{defn}

\begin{explain}
By \olref[stm]{prop:standard-domain}, any standard !!{structure}
for~$\Lang{L_A}$ contains only standard !!{element}s. Consequently, a
non-standard !!{structure} must contain at least one non-standard
element. In fact, the existence of a non-standard !!{element}
guarantees that the !!{structure} is non-standard.
\end{explain}

target:
\begin{explain}
د~\olref[stm]{prop:standard-domain} له مخې د~$\Lang{L_A}$ هر
معياري !!{structure} يوازې معياري !!{element}s لري۔ نو يو نامعياري
!!{structure} بايد لږ تر لږه يو نامعياري عنصر ولري۔ په حقيقت کښې،
د يوه نامعياري !!{element} شتون دا تضمينوي چې !!{structure}
نامعياري دے۔
\end{explain}

