\begin{lem}
\ollabel{lem:lindstrom}
Suppose $!E \in L(\Lang{L})$, with $\Lang{L}$ finite, and assume
also that there is an $n \in \Nat$ such that for any two
!!{structure}s $\Struct{M}$ and~$\Struct{N}$, if $\Struct{M} \equiv_n
\Struct{N}$ and $\Struct{M} \models_L !E$ then also $\Struct{N}
\models_L !E$. Then $!E$ is equivalent to a first-order
!!{sentence}, i.e., there is a first-order $!D$ such that
$\Mod(L){!E} = \Mod(L){!D}$.
\end{lem}

target:
\begin{lem}
\ollabel{lem:lindstrom}
فرض کړئ~$!E \in L(\Lang{L})$ او~$\Lang{L}$ متناهي ده؛ دا هم فرض
کړئ چې داسې~$n \in \Nat$ شته چې د هر دوو !!{structure}s
$\Struct{M}$ او~$\Struct{N}$ دپاره، که~$\Struct{M} \equiv_n
\Struct{N}$ او~$\Struct{M} \models_L !E$ وي، نو
$\Struct{N} \models_L !E$ هم وي۔ بيا~$!E$ د لومړۍ درجې له يوې
!!{sentence} سره هم‌ارزه ده؛ يعنې د لومړۍ درجې داسې~$!D$ شته چې
$\Mod(L){!E} = \Mod(L){!D}$ وي۔
\end{lem}

