source:
\begin{thm}
\ollabel{thm:s-m-n}
  For each pair of natural numbers $n$ and~$m$, there is a primitive
  recursive function~$s^m_n$ such that for every sequence
  $e$, $a_0$, \dots, $a_{m-1}$, $y_0$ ,\dots, $y_{n-1}$, we have
  \[
  \cfind{s^m_n(e, a_0, \dots, a_{m-1})}[n](y_0, \dots, y_{n-1}) \simeq
  \cfind{e}[m+n](a_0, \dots, a_{m-1}, y_0, \dots, y_{n-1}).
\]
\end{thm}

target:
\begin{thm}
\ollabel{thm:s-m-n}
  د طبيعي عددونو د هرې جوړې $n$ او~$m$ دپاره يوه بنسټيزه بازګشتي
  تابع~$s^m_n$ شته، داسې چې د هرې لړۍ
  $e$، $a_0$، \dots، $a_{m-1}$، $y_0$، \dots، $y_{n-1}$ دپاره لرو:
  \[
  \cfind{s^m_n(e, a_0, \dots, a_{m-1})}[n](y_0, \dots, y_{n-1}) \simeq
  \cfind{e}[m+n](a_0, \dots, a_{m-1}, y_0, \dots, y_{n-1}).
\]
\end{thm}

source:
\begin{thm}
\ollabel{thm:univ-comp}
There is a universal partial computable function~$\fn{Un}(e,x)$. In other
words, there is a function $\fn{Un}(e,x)$ such that:
\begin{enumerate}
\item $\fn{Un}(e,x)$ is partial computable.
\item If $f(x)$ is any partial computable function, then there is a
natural number $e$ such that $f(x) \simeq \fn{Un}(e,x)$ for every~$x$.
\end{enumerate}
\end{thm}

target:
\begin{thm}
\ollabel{thm:univ-comp}
يوه نړيواله جزوي محاسبه کېدونکې تابع~$\fn{Un}(e,x)$ شته۔ په بله
وينا، داسې تابع $\fn{Un}(e,x)$ شته چې:
\begin{enumerate}
\item $\fn{Un}(e,x)$ جزوي محاسبه کېدونکې ده۔
\item که $f(x)$ هره جزوي محاسبه کېدونکې تابع وي، نو يو طبيعي عدد
$e$ شته، داسې چې د هر~$x$ دپاره $f(x) \simeq \fn{Un}(e,x)$ وي۔
\end{enumerate}
\end{thm}

source:
\begin{proof}
Let $\fn{Un}(e,x) \simeq U(\umin{s}{T(e,x,s)})$, where $U$ and $T$ are
as in Kleene's normal form theorem (\olref[nfm]{thm:normal-form}).
\end{proof}

target:
\begin{proof}
$\fn{Un}(e,x) \simeq U(\umin{s}{T(e,x,s)})$ وټاکئ، چې~$U$ او~$T$
د کليني د نورمال شکل په قضيه کښې د
(\olref[nfm]{thm:normal-form}) په شان دي۔
\end{proof}

source:
\begin{thm}
\ollabel{thm:no-univ}
There is no universal computable function. In other words, any
function $\fn{Un}'(k, x)$ which is such that if $f(x)$ is a total
computable function, then there is a natural number~$k$ such that
$f(x) = \fn{Un}'(k,x)$ for every~$x$, is not computable.
\end{thm}

target:
\begin{thm}
\ollabel{thm:no-univ}
هېڅ نړيواله محاسبه کېدونکې تابع نشته۔ په بله وينا، هره تابع
$\fn{Un}'(k, x)$ چې دا ځانګړنه ولري چې که $f(x)$ هرځاے تعريف شوې
محاسبه کېدونکې تابع وي، نو يو طبيعي عدد~$k$ شته، داسې چې د هر~$x$
دپاره $f(x) = \fn{Un}'(k,x)$ وي، محاسبه کېدونکې نۀ ده۔
\end{thm}

\begin{explain}
پورته \olref[uni]{thm:univ-comp} ښيي چې له دې قطري استدلاله وتلے شو،
خو يوازې په دې بيه چې نړيواله تابع جزوي ومنو۔ يعنې~$\fn{Un}$ د هرځاے
تعريف شويو محاسبه کېدونکو تابعو دپاره نړيواله ده، خو پخپله هرځاے
تعريف شوې نۀ ده۔ قطري استدلال په جزوي حالت کښې کار نۀ کوي۔
\end{explain}

source:
\begin{thm}
\ollabel{thm:halting-problem}
Let
\[
h(e, x)  =
\begin{cases}
1 & \text{if\/ $\fn{Un}(e, x)$ is defined} \\
0 & \text{otherwise.}
\end{cases}
\]
Then $h$ is not computable.
\end{thm}

target:
\begin{thm}
\ollabel{thm:halting-problem}
فرض کړئ
\[
h(e, x)  =
\begin{cases}
1 & \text{که $\fn{Un}(e, x)$ تعريف شوې وي} \\
0 & \text{که داسې نۀ وي۔}
\end{cases}
\]
نو $h$ محاسبه کېدونکې نۀ ده۔
\end{thm}

source:
\begin{proof}
Suppose $h$ is computable. We show that this would let us define a
universal computable function. Define
\[
\fn{Un'}(e,x) =
\begin{cases}
\fn{Un}(e,x) & \text{if $h(e,x) = 1$} \\
0 & \text{otherwise.}
\end{cases}
\]
But now $\fn{Un'}(e, x)$ is a total function, and is computable if~$h$
is. For instance, we could define $g$ using primitive recursion, by
\begin{align*}
g(0, e, x) & \simeq 0 \\
g(y+1, e, x) & \simeq \fn{Un}(e,x);
\end{align*}
then
\[
\fn{Un'}(e,x) \simeq g(h(e,x),e,x).
\]
Since $\fn{Un'}(e,x)$ agrees with $\fn{Un}(e,x)$ wherever the latter
is defined, $\fn{Un'}$ is universal for those partial computable
functions that happen to be total. But this contradicts
\olref[nou]{thm:no-univ}.
\end{proof}

target:
\begin{proof}
فرض کړئ $h$ محاسبه کېدونکې ده۔ ښيو چې په دې سره يوه نړيواله محاسبه
کېدونکې تابع تعريفولے شو۔ داسې تعريف کړئ:
\[
\fn{Un'}(e,x) =
\begin{cases}
\fn{Un}(e,x) & \text{که $h(e,x) = 1$ وي} \\
0 & \text{که داسې نۀ وي۔}
\end{cases}
\]
خو اوس $\fn{Un'}(e, x)$ هرځاے تعريف شوې تابع ده، او که~$h$ محاسبه
کېدونکې وي نو دا هم محاسبه کېدونکې ده۔ د بېلګې په توګه، د بنسټيز
بازګښت په کارولو سره~$g$ داسې تعريفولے شو:
\begin{align*}
g(0, e, x) & \simeq 0 \\
g(y+1, e, x) & \simeq \fn{Un}(e,x);
\end{align*}
بيا
\[
\fn{Un'}(e,x) \simeq g(h(e,x),e,x).
\]
څرنګه چې $\fn{Un'}(e,x)$ په هر هغه ځاے کښې له~$\fn{Un}(e,x)$ سره
برابره ده چې وروستۍ تابع تعريف شوې وي، نو~$\fn{Un'}$ د هغو جزوي
محاسبه کېدونکو تابعو دپاره نړيواله ده چې هرځاے تعريف شوې وي۔ خو دا له
\olref[nou]{thm:no-univ} سره تناقض دے۔
\end{proof}

source:
\begin{defn}
  Let $S$ be a set of natural numbers. Then $S$ is \emph{computable}
  iff its characteristic function~$\Char{S}$ is. In other words,
  $S$~is computable iff the function
\[
\Char{S}(x) =
\begin{cases}
1 & \text{if $x \in S$} \\
0 & \text{otherwise}
\end{cases}
\]
is computable. Similarly, a relation $R(x_0, \dots, x_{k-1})$ is
computable if and only if its characteristic function is.

\begin{explain}
Notice that we now have a number of notions of computability: for
partial functions, for functions, and for sets. Do not get them
confused!{} \iftag{TMs}{The Turing machine computing a partial function
  returns the output of the function, for input values at which the
  function is defined; the Turing machine computing a set returns
  either $1$ or~$0$, after deciding whether or not the input value is in
  the set or not.}{}
\end{explain}

target:
\begin{explain}
پام وکړئ چې اوس د محاسبه کېدنې څو مفهومونه لرو: د جزوي تابعو، تابعو
او سټونو دپاره۔ دا سره ګډ نۀ کړئ!{} \iftag{TMs}{هغه ټيورينګ ماشين چې
  جزوي تابع محاسبه کوي، د تابع په هغو ننوتونو کښې ئې وت راګرځوي چې
  تابع پرې تعريف شوې وي؛ هغه ټيورينګ ماشين چې يو سټ محاسبه کوي، تر
  دې پرېکړې وروسته چې ننوت په سټ کښې دے که نه، يا~$1$ يا~$0$
  راګرځوي۔}{}
\end{explain}

source:
\begin{defn}
A set is \emph{computably enumerable} if it is empty or the range of a
computable function.
\end{defn}

target:
\begin{defn}
يو سټ هغه وخت \emph{په محاسبوي ډول د شمېر وړ} دے چې تش وي يا د يوې
محاسبه کېدونکې تابع د قيمتونو سټ وي۔
\end{defn}

source:
\begin{history}
Computably enumerable sets are also called \emph{recursively
  enumerable} instead. This is the original terminology, and today
both are commonly used, as well as the abbreviations ``c.e.'' and
``r.e.''
\end{history}

target:
\begin{history}
په محاسبوي ډول د شمېر وړ سټونه د دې پر ځاے \emph{په بازګشتي ډول د
  شمېر وړ} سټونه هم بلل کېږي۔ دا اصلي اصطلاح ده، او نن دواړه نومونه،
او ورسره لنډونونه ``c.e.'' او ``r.e.''، په عام ډول کارېږي۔
\end{history}

source:
\begin{thm}
\ollabel{thm:ce-equiv}
Let $S$ be a set of natural numbers. Then the following are
equivalent:
\begin{enumerate}
\item\ollabel{case:ce} $S$ is computably enumerable.
\item\ollabel{case:ran-pc} $S$ is the range of a \emph{partial} computable function.
\item\ollabel{case:ran-prim} $S$ is empty or the range of a primitive recursive function.
\item\ollabel{case:ce-domain} $S$ is the \emph{domain} of a partial computable function.
\end{enumerate}
\end{thm}

target:
\begin{thm}
\ollabel{thm:ce-equiv}
فرض کړئ $S$ د طبيعي عددونو يو سټ دے۔ بيا لاندې خبرې سره معادلې دي:
\begin{enumerate}
\item\ollabel{case:ce} $S$ په محاسبوي ډول د شمېر وړ دے۔
\item\ollabel{case:ran-pc} $S$ د يوې \emph{جزوي} محاسبه کېدونکې تابع
د قيمتونو سټ دے۔
\item\ollabel{case:ran-prim} $S$ تش دے يا د يوې بنسټيزې بازګشتي تابع
د قيمتونو سټ دے۔
\item\ollabel{case:ce-domain} $S$ د يوې جزوي محاسبه کېدونکې تابع
\emph{د تعريف ساحه} ده۔
\end{enumerate}
\end{thm}

source:
\begin{proof}
Since every primitive recursive function is computable and every
computable function is partial computable, \olref{case:ran-prim}
implies \olref{case:ce} and \olref{case:ce}
implies~\olref{case:ran-pc}. (Note that if $S$ is empty, $S$~is the
range of the partial computable function that is nowhere defined.) If
we show that \olref{case:ran-pc} implies \olref{case:ran-prim}, we
will have shown the first three clauses equivalent.

\begin{thm}
\ollabel{thm:exists-char}
A set $S$ is computably enumerable if and only if there is a
computable relation $R(x,y)$ such that
\[
S = \Setabs{ x }{ \lexists[y][R(x,y)] }.
\]
\end{thm}

target:
\begin{thm}
\ollabel{thm:exists-char}
سټ~$S$ هله او يوازې هله په محاسبوي ډول د شمېر وړ دے چې داسې محاسبه
کېدونکې اړيکه~$R(x,y)$ وي چې
\[
S = \Setabs{ x }{ \lexists[y][R(x,y)] }.
\]
\end{thm}

source:
\begin{thm}\ollabel{thm:K-0}
Let $K_0$ be the set $\Setabs{\tuple{e, x}}{\cfind{e}(x) \fdefined}$.
Then $K_0$ is computably enumerable but not computable.
\end{thm}

target:
\begin{thm}\ollabel{thm:K-0}
فرض کړئ $K_0$ سټ $\Setabs{\tuple{e, x}}{\cfind{e}(x) \fdefined}$
دے۔ بيا $K_0$ په محاسبوي ډول د شمېر وړ دے، خو محاسبه کېدونکے نۀ دے۔
\end{thm}

source:
The fact that $K_0$ is not computable is just the undecidability of
the halting problem, \olref[hlt]{thm:halting-problem}.
\end{proof}

target:
دا حقيقت چې $K_0$ محاسبه کېدونکے نۀ دے، هماغه د درېدنې د مسئلې
ناپرېکړتيا ده، \olref[hlt]{thm:halting-problem}۔
\end{proof}

source:
\begin{thm}\ollabel{thm:K}
The self-halting set $K = \Setabs{e}{\cfind{e}(e) \fdefined}$ is
!!{c.e.} but not decidable.
\end{thm}

target:
\begin{thm}\ollabel{thm:K}
پر خپل ځان د درېدنې سټ
$K = \Setabs{e}{\cfind{e}(e) \fdefined}$، !!{c.e.} دے خو د پرېکړې
وړ نۀ دے۔
\end{thm}

source:
\begin{proof}
  Suppose $K$ is decidable, i.e., its characteristic function
  $\Char{K}$ is computable. Let 
  \[d(e) = \begin{cases}
  1 & \text{if\/ $\Char{K}(e) = 0$}\\
  \fundefined & \text{otherwise.}
  \end{cases}
  \] 
  Let $k$ be the index of~$d$, i.e., $d \simeq \cfind{k}$. Then $d(k)
  \simeq \cfind{k}(k)$. This contradicts the fact that $d(k)
  \fdefined$ iff $\cfind{k}(k) \fundefined$, which follows from the
  definition of~$d$.

target:
\begin{proof}
  فرض کړئ $K$ د پرېکړې وړ دے، يعنې ځانګړونکې تابع~$\Char{K}$ ئې
  محاسبه کېدونکې ده۔ وټاکئ:
  \[d(e) = \begin{cases}
  1 & \text{که $\Char{K}(e) = 0$ وي}\\
  \fundefined & \text{که داسې نۀ وي۔}
  \end{cases}
  \]
  فرض کړئ $k$ د~$d$ شاخص دے، يعنې $d \simeq \cfind{k}$۔ بيا
  $d(k) \simeq \cfind{k}(k)$ ده۔ دا له هغه حقيقت سره تناقض لري چې
  $d(k) \fdefined$ هله او يوازې هله چې
  $\cfind{k}(k) \fundefined$ وي، او دا د~$d$ له تعريفه راځي۔

  $K$ د تابع $f(x) = \umin{y}{T(x,x,y)}$ د تعريف ساحه ده او ځکه
  !!{c.e.} دے۔
\end{proof}

source:
\begin{thm}
Suppose $A$ and $B$ are computably enumerable. Then so are $A \cap B$
and $A \cup B$.
\end{thm}

target:
\begin{thm}
فرض کړئ $A$ او~$B$ په محاسبوي ډول د شمېر وړ دي۔ بيا $A \cap B$ او
$A \cup B$ هم په محاسبوي ډول د شمېر وړ دي۔
\end{thm}

source:
\begin{explain}
Here is what is going on, in computational terms: given
procedures that enumerate $A$ and $B$, we can semi-decide if an
element $x$ is in $A \cup B$ by looking for $x$ in either enumeration;
and we can semi-decide if an element $x$ is in $A \cap B$ for looking
for $x$ in both enumerations at the same time.
\end{explain}

For the second proof, suppose again that $A$ is enumerated by~$f$ and
$B$ is enumerated by~$g$. Let
\[
k(x) = \begin{cases}
f(x/2) & \text{if $x$ is even} \\
g((x-1)/2) & \text{if $x$ is odd.}
\end{cases}
\]
Then $k$ enumerates $A \cup B$; the idea is that $k$ just alternates
between the enumerations offered by $f$ and~$g$. Enumerating $A \cap
B$ is tricker. If $A \cap B$ is empty, it is trivially computably
enumerable. Otherwise, let $c$ be any element of $A \cap B$, and
define $l$ by
\[
l(x) = \begin{cases}
f((x)_0) & \text{if $f((x)_0) = g((x)_1)$} \\
c & \text{otherwise.}
\end{cases}
\]
In computational terms, $l$ runs through pairs of elements in the
enumerations of $f$ and $g$, and outputs every match it finds;
otherwise, it just stalls by outputting $c$.

\begin{explain}
In computational terms, if $A$ is the set of values for which
$m$ halts and $B$ is the set of values for which $n$ halts, $A \cap B$
is the set of values for which both procedures halt.
\end{explain}

target:
\begin{explain}
په محاسبوي ژبه کښې، که~$A$ د هغو قيمتونو سټ وي چې~$m$ پرې درېږي او
$B$ د هغو قيمتونو سټ وي چې~$n$ پرې درېږي، نو $A \cap B$ د هغو
قيمتونو سټ دے چې دواړه کړنلارې پرې درېږي۔
\end{explain}

source:
\begin{thm}
\ollabel{thm:ce-comp}
Let $A$ be any set of natural numbers. Then $A$ is computable if and
only if both $A$ and $\Complement{A}$ are computably enumerable.
\end{thm}

target:
\begin{thm}
\ollabel{thm:ce-comp}
فرض کړئ $A$ د طبيعي عددونو هر يو سټ دے۔ بيا $A$ هله او يوازې هله
محاسبه کېدونکے دے چې $A$ او~$\Complement{A}$ دواړه په محاسبوي ډول
د شمېر وړ وي۔
\end{thm}

source:
\begin{explain}
It is easier to understand what is going on in informal computational
terms: to decide $A$, on input $x$ search for halting computations of
$\cfind{e}$ and $\cfind{f}$. One of them is bound to halt; if it is $\cfind{e}$,
then $x$ is in~$A$, and otherwise, $x$ is in~$\Complement{A}$.
\end{explain}

\begin{cor}
\ollabel{cor:comp-k}
$\Complement{K_0}$ is not computably enumerable.
\end{cor}

target:
\begin{cor}
\ollabel{cor:comp-k}
$\Complement{K_0}$ په محاسبوي ډول د شمېر وړ نۀ دے۔
\end{cor}

source:
\begin{proof}
We know that $K_0$ is computably enumerable, but not computable. If
$\Complement{K_0}$ were computably enumerable, then $K_0$ would be
computable by \olref{thm:ce-comp}, contradicting \olref[ncp]{thm:K-0}.
\end{proof}

target:
\begin{proof}
موږ پوهېږو چې~$K_0$ په محاسبوي ډول د شمېر وړ دے، خو محاسبه کېدونکے
نۀ دے۔ که~$\Complement{K_0}$ په محاسبوي ډول د شمېر وړ وای، نو د
\olref{thm:ce-comp} له مخې به~$K_0$ محاسبه کېدونکے و، چې له
\olref[ncp]{thm:K-0} سره تناقض دے۔
\end{proof}

\begin{defn}
فرض کړئ $A$ او~$B$ د طبيعي عددونو سټونه دي۔ محاسبه کېدونکې تابع
~$f\colon \Nat \to \Nat$ له~$A$ څخه~$B$ ته \emph{ډېر-پر-يو راکمونه}
ده، هله او يوازې هله چې د هر طبيعي عدد~$x$ دپاره
\[
x \in A \quad \text{هله او يوازې هله چې} \quad f(x) \in B.
\]
که داسې راکمونه~$f$ شته، وايو~$A$، $B$ ته \emph{ډېر-پر-يو راکمېدونکے}
دے، چې $A \leq_m B$ ليکل کېږي۔ که~$A$، $B$ ته ډېر-پر-يو راکمېدونکے
وي او برعکس هم، نو~$A$ او~$B$ \emph{ډېر-پر-يو معادل} بلل کېږي، چې
$A \equiv_m B$ ليکل کېږي۔
\end{defn}

source:
\begin{digress}
It is true, but by no means obvious, that one-one reducibility really
is a stronger requirement than many-one reducibility. In other words,
there are infinite sets $A$ and~$B$ such that $A$ is many-one
reducible to~$B$ but not one-one reducible to~$B$.
\end{digress}

target:
\begin{digress}
دا رښتيا ده، خو هېڅ څرګنده نۀ ده، چې يو-پر-يو راکمېدنه په رښتيا د
ډېر-پر-يو راکمېدنې په پرتله پياوړے شرط دے۔ په بله وينا، داسې نامتناهي
سټونه~$A$ او~$B$ شته چې~$A$، $B$ ته ډېر-پر-يو راکمېدونکے وي خو
~$B$ ته يو-پر-يو راکمېدونکے نۀ وي۔
\end{digress}

source:
\begin{prop}
\ollabel{prop:trans-red}
If $A \leq_m B$ and $B \leq_m C$, then $A \leq_m C$.
\end{prop}

target:
\begin{prop}
\ollabel{prop:trans-red}
که $A \leq_m B$ او $B \leq_m C$ وي، نو $A \leq_m C$۔
\end{prop}

source:
\begin{proof}
Composing a reduction of $A$ to~$B$ with a reduction of $B$ to
$C$ yields a reduction of $A$ to~$C$.
\end{proof}

target:
\begin{proof}
له~$A$ څخه~$B$ ته د راکمونې او له~$B$ څخه~$C$ ته د راکمونې ترکيب
له~$A$ څخه~$C$ ته راکمونه ورکوي۔
\end{proof}

source:
\begin{prob}
Prove \olref{prop:trans-red} by showing that if $f$ and~$g$ are
many-one reductions of $A$ to~$B$ and $B$ to~$C$, respectively, then
$\comp{f}{g}$ is a many-one reduction of $A$ to~$C$.
\end{prob}

target:
\begin{prob}
\olref{prop:trans-red} په دې ښودلو ثابت کړئ چې که~$f$ او~$g$ په
ترتيب سره له~$A$ څخه~$B$ او له~$B$ څخه~$C$ ته ډېر-پر-يو راکمونې
وي، نو~$\comp{f}{g}$ له~$A$ څخه~$C$ ته ډېر-پر-يو راکمونه ده۔
\end{prob}

source:
\begin{prop}
\ollabel{prop:reduce}
Let $A$ and $B$ be any sets, and suppose $A \leq_m B$.
\begin{enumerate}
\item If $B$ is computably enumerable, so is~$A$.
\item If $B$ is computable, so is~$A$.
\end{enumerate}
\end{prop}

target:
\begin{prop}
\ollabel{prop:reduce}
فرض کړئ $A$ او~$B$ هر سټونه دي، او $A \leq_m B$۔
\begin{enumerate}
\item که~$B$ په محاسبوي ډول د شمېر وړ وي، نو~$A$ هم داسې دے۔
\item که~$B$ محاسبه کېدونکے وي، نو~$A$ هم داسې دے۔
\end{enumerate}
\end{prop}

source:
\begin{proof}
Let $f$ be a many-one reduction from $A$ to~$B$. For the first
claim, just check that if $B$ is the domain of a partial function~$g$,
then $A$ is the domain of~$\comp{f}{g}$:
\begin{align*}
x \in A & \text{ iff } f(x) \in B \\
& \text{ iff }  g(f(x)) \fdefined.
\end{align*}

target:
\begin{proof}
$f$ له~$A$ څخه~$B$ ته ډېر-پر-يو راکمونه وي۔ د لومړۍ دعوې دپاره بس
دا وازمويئ چې که~$B$ د جزوي تابع~$g$ د تعريف ساحه وي، نو~$A$ د
~$\comp{f}{g}$ د تعريف ساحه ده:
\begin{align*}
x \in A & \text{ هله او يوازې هله چې } f(x) \in B \\
& \text{ هله او يوازې هله چې }  g(f(x)) \fdefined.
\end{align*}

source:
\begin{prob}
Suppose $f$ is a many-one reduction of $A$ to~$B$. Show that $f$ is
also a many-one reduction of $\Complement{A}$ to $\Complement{B}$.
\end{prob}

target:
\begin{prob}
فرض کړئ~$f$ له~$A$ څخه~$B$ ته ډېر-پر-يو راکمونه ده۔ وښيئ چې~$f$ له
$\Complement{A}$ څخه~$\Complement{B}$ ته هم ډېر-پر-يو راکمونه ده۔
\end{prob}

source:
\begin{prob}
Show that if $f\colon A \to B$ is a many-one reduction, then $\Char{A}
= \comp{f}{\Char{B}}$.
\end{prob}

\begin{defn}
A set $A$ is a \emph{complete !!{computably enumerable} set}
(under many-one reducibility) if
\begin{enumerate}
\item $A$ is computably enumerable, and
\item for any other computably enumerable set $B$, $B \leq_m A$.
\end{enumerate}
\end{defn}

target:
\begin{defn}
سټ~$A$ (د ډېر-پر-يو راکمېدنې لاندې) يو
\emph{بشپړ !!{computably enumerable} سټ} دے، که
\begin{enumerate}
\item $A$ په محاسبوي ډول د شمېر وړ وي، او
\item د هر بل په محاسبوي ډول د شمېر وړ سټ~$B$ دپاره $B \leq_m A$ وي۔
\end{enumerate}
\end{defn}

source:
\begin{thm}
$K$, $K_0$, and $K_1$ are all complete computably enumerable sets.
\end{thm}

target:
\begin{thm}
$K$، $K_0$ او~$K_1$ ټول بشپړ په محاسبوي ډول د شمېر وړ سټونه دي۔
\end{thm}

source:
\begin{prob}
Give a reduction of $K$ to $K_0$.
\end{prob}

target:
\begin{prob}
له~$K$ څخه~$K_0$ ته يوه راکمونه ورکړئ۔
\end{prob}

\begin{digress}
نو څرګنده شوه چې تر اوسه مو د په محاسبوي ډول د شمېر وړ سټونو هره
کتلې بېلګه يا محاسبه کېدونکې ده، يا بشپړه۔ دا بايد عجيبه وبرېښي!{}
ايا داسې په محاسبوي ډول د شمېر وړ سټونه شته چې نۀ محاسبه کېدونکي او
نۀ بشپړ وي؟ ځواب هو دے، خو دا تر هغه وخته نۀ وه ثابته شوې چې د
۱۹۵۰مو کلونو په منځ کښې فريډبرګ او موچنيک په خپلواکه توګه ثابته کړه۔
\end{digress}

source:
\begin{prop}
\ollabel{prop:k1}
Let
\[
K_1 = \Setabs{e}{\cfind{e}(0) \fdefined}.
\]
Then $K_1$ is computably enumerable but not computable.
\end{prop}

target:
\begin{prop}
\ollabel{prop:k1}
فرض کړئ
\[
K_1 = \Setabs{e}{\cfind{e}(0) \fdefined}.
\]
بيا $K_1$ په محاسبوي ډول د شمېر وړ دے، خو محاسبه کېدونکے نۀ دے۔
\end{prop}

source:
\begin{proof}
Since $K_1 = \Setabs{e}{\lexists[s][T(e,0,s)]}$, $K_1$ is computably
enumerable by \olref[eqc]{thm:exists-char}.

\begin{explain}
In terms of the informal argument above, $s(e,x,y)$ is an index for
the machine that, for any input $z$, ignores that input and computes
$\cfind{x}(y)$.
\end{explain}

target:
\begin{explain}
د پورته غير رسمي استدلال په ژبه، $s(e,x,y)$ د هغه ماشين شاخص دے چې
د هر ننوت~$z$ دپاره هغه ننوت له پامه غورځوي او~$\cfind{x}(y)$
محاسبه کوي۔
\end{explain}

source:
\begin{prop}
\ollabel{prop:total}
$\fn{Tot}$ is not computable.
\end{prop}

target:
\begin{prop}
\ollabel{prop:total}
$\fn{Tot}$ محاسبه کېدونکے نۀ دے۔
\end{prop}

source:
Using the $s$-$m$-$n$ theorem, there is a primitive recursive
function~$k(x)$ such that for every $x$ and~$y$,
\[
\cfind{k(x)}(y) =
\begin{cases}
0 & \text{if $x \in K$} \\
\fundefined & \text{otherwise}
\end{cases}
\]
So $\cfind{k(x)}$ is total if $x \in K$, and undefined otherwise. Thus,
$k$ is a reduction of $K$ to~$\fn{Tot}$.
\end{proof}

target:
د~$s$-$m$-$n$ قضيې په کارولو داسې بنسټيزه بازګشتي تابع~$k(x)$ شته
چې د هر~$x$ او~$y$ دپاره
\[
\cfind{k(x)}(y) =
\begin{cases}
0 & \text{که $x \in K$ وي} \\
\fundefined & \text{که داسې نۀ وي۔}
\end{cases}
\]
نو~$\cfind{k(x)}$ هله هرځاے تعريف شوې ده چې~$x \in K$ وي، او که نه
نو تعريف شوې نۀ ده۔ په دې توګه~$k$ له~$K$ څخه~$\fn{Tot}$ ته راکمونه
ده۔
\end{proof}

source:
\begin{digress}
It turns out that $\fn{Tot}$ is not even computably enumerable---its
complexity lies further up on the ``arithmetical hierarchy.''  But we
will not worry about this strengthening here.
\end{digress}

target:
\begin{digress}
په حقيقت کښې~$\fn{Tot}$ آن په محاسبوي ډول د شمېر وړ هم نۀ دے؛
پېچلتيا ئې د ``حسابي پوړيز نظام'' په لا لوړه برخه کښې پرته ده۔ خو
دلته به د دې پياوړتيا په اړه اندېښنه نۀ کوو۔
\end{digress}

source:
Rice's theorem is very powerful. The following immediate corollary
shows some sample applications.
\begin{cor}
The following sets are undecidable.
\begin{enumerate}
\item $\Setabs{x}{\text{$17$ is in the range of $\cfind{x}$}}$
\item $\Setabs{x}{\text{$\cfind{x}$ is constant}}$
\item $\Setabs{x}{\text{$\cfind{x}$ is total}}$
\item $\Setabs{x}{\text{whenever $y < y'$, $\cfind{x}(y) \fdefined$, and
    if $\cfind{x}(y') \fdefined$, then $\cfind{x}(y) < \cfind{x}(y')$}}$
\end{enumerate}
\end{cor}

target:
د رايس قضيه ډېره پياوړې ده۔ لاندې سمدستي نتيجه ئې د کارونې څو
بېلګې ښيي۔
\begin{cor}
لاندې سټونه د پرېکړې وړ نۀ دي۔
\begin{enumerate}
\item $\Setabs{x}{\text{$17$ د $\cfind{x}$ په قيمتونو کښې دے}}$
\item $\Setabs{x}{\text{$\cfind{x}$ ثابته ده}}$
\item $\Setabs{x}{\text{$\cfind{x}$ هرځاے تعريف شوې ده}}$
\item $\Setabs{x}{\text{هر کله چې $y < y'$، $\cfind{x}(y) \fdefined$، او
    که $\cfind{x}(y') \fdefined$، نو $\cfind{x}(y) < \cfind{x}(y')$}}$
\end{enumerate}
\end{cor}

source:
\begin{proof}
  These are all nontrivial index sets.
\end{proof}

target:
\begin{proof}
  دا ټول غيرابتذالي شاخصي سټونه دي۔
\end{proof}

source:
Question: is there a computable function $h$, with the
following property? For every $x$ and $y$,
\[
h(\gn{\cfind{x}(y)}) =
\begin{cases}
1 & \text{if $\cfind{x}(y) \fdefined$} \\
0 & \text{otherwise.}
\end{cases}
\]

target:
پوښتنه: ايا داسې محاسبه کېدونکې تابع~$h$ شته چې لاندې خاصيت ولري؟ د
هر~$x$ او~$y$ دپاره
\[
h(\gn{\cfind{x}(y)}) =
\begin{cases}
1 & \text{که $\cfind{x}(y) \fdefined$ وي} \\
0 & \text{که داسې نۀ وي۔}
\end{cases}
\]

source:
Answer: No; otherwise, the partial function
\[
g(x) \simeq
\begin{cases}
0 & \text{if $h(\gn{\cfind{x}(x)}) = 0$} \\
\text{undefined} & \text{otherwise}
\end{cases}
\]
would be computable, and so have some index~$e$. But then we have
\[
\cfind{e}(e) \simeq
\begin{cases}
0 & \text{if $h(\gn{\cfind{e}(e)}) = 0$} \\
\text{undefined} & \text{otherwise,}
\end{cases}
\]
in which case $\cfind{e}(e)$ is defined if and only if it isn't, a
contradiction.

target:
ځواب: نه؛ که نه، دا جزوي تابع
\[
g(x) \simeq
\begin{cases}
0 & \text{که $h(\gn{\cfind{x}(x)}) = 0$ وي} \\
\text{تعريف شوې نۀ ده} & \text{که داسې نۀ وي}
\end{cases}
\]
به محاسبه کېدونکې وه، او ځکه به ئې کوم شاخص~$e$ درلود۔ خو بيا لرو:
\[
\cfind{e}(e) \simeq
\begin{cases}
0 & \text{که $h(\gn{\cfind{e}(e)}) = 0$ وي} \\
\text{تعريف شوې نۀ ده} & \text{که داسې نۀ وي،}
\end{cases}
\]
چې په دې صورت کښې~$\cfind{e}(e)$ هله او يوازې هله تعريف شوې ده چې
تعريف شوې نۀ وي، او دا تناقض دے۔

source:
\begin{lem}
\ollabel{lem:fixed-equiv}
The following statements are equivalent:
\begin{enumerate}
\item For every partial computable function $g(x,y)$, there is an
  index~$e$ such that for every~$y$,
\[
\cfind{e}(y) \simeq g(e,y).
\]
\item For every computable function~$f(x)$, there is an index~$e$ such
  that for every~$y$,
\[
\cfind{e}(y) \simeq \cfind{f(e)}(y).
\]
\end{enumerate}
\end{lem}

target:
\begin{lem}
\ollabel{lem:fixed-equiv}
لاندې بيانونه معادل دي:
\begin{enumerate}
\item د هرې جزوي محاسبه کېدونکې تابع~$g(x,y)$ دپاره داسې شاخص~$e$
  شته چې د هر~$y$ دپاره
\[
\cfind{e}(y) \simeq g(e,y).
\]
\item د هرې محاسبه کېدونکې تابع~$f(x)$ دپاره داسې شاخص~$e$ شته چې
  د هر~$y$ دپاره
\[
\cfind{e}(y) \simeq \cfind{f(e)}(y).
\]
\end{enumerate}
\end{lem}

