source:
\begin{defn}\ollabel{defn:disciplined}
A Turing machine~$M$ is \emph{disciplined} iff
\begin{enumerate}
    \item it has a designated single halting state~$h$,
    \item it halts, if it halts at all, while scanning square~$1$,
    \item it never erases the $\TMendtape$ symbol on square~$0$, and
    \item it never attempts to move left from square~$0$.
\end{enumerate}
\end{defn}

target:
\begin{defn}\ollabel{defn:disciplined}
ټيورينګ ماشين~$M$ هله او يوازې هله \emph{منضبط} دے چې
\begin{enumerate}
    \item يو ټاکلی يوازينی درېدنی حالت~$h$ ولري،
    \item که بېخي درېږي، د مربع~$1$ د لوستلو پر وخت ودرېږي،
    \item پر مربع~$0$ د~$\TMendtape$ نښه هېڅکله پاکه نۀ کړي، او
    \item له مربع~$0$ څخه کيڼ لوري ته د تلو هڅه هېڅکله ونۀ کړي۔
\end{enumerate}
\end{defn}

