source:
\begin{thm}\ollabel{thm:universal-tm} There is a \emph{universal
  Turing machine}~$U$ which, when started on input $\tuple{e,n}$ 
  \begin{enumerate}
    \item halts iff $M_e$ halts on input~$n$, and
    \item if $M_e$ halts with output $m$, so does~$U$.
  \end{enumerate}
  $U$ thus computes the function $f\colon \Nat \times \Nat \pto \Nat$
  given by $f(e,n) = m$ if $M_e$ started on input~$n$ halts with
  output~$m$, and undefined otherwise.
\end{thm}

target:
\begin{thm}\ollabel{thm:universal-tm} داسې يو \emph{نړيوال ټيورينګ
  ماشين}~$U$ شته چې کله پر ننوت~$\tuple{e,n}$ پيل شي،
  \begin{enumerate}
    \item هله او يوازې هله درېږي چې~$M_e$ پر ننوت~$n$ ودرېږي، او
    \item که~$M_e$ له وت~$m$ سره ودرېږي، نو~$U$ هم همداسې کوي۔
  \end{enumerate}
  نو~$U$ هغه تابع~$f\colon \Nat \times \Nat \pto \Nat$ محاسبه کوي
  چې~$f(e,n) = m$ وي که~$M_e$ پر ننوت~$n$ له پيل وروسته له وت~$m$
  سره ودرېږي، او که نۀ وي نو ناتعريفه ده۔
\end{thm}

