source:
\begin{proof}
  Let $\Struct{M'}$ be as in the proof of
  \olref[ver]{lem:halt-if-valid}, except
  \begin{align*}
    \Domain{M'} & = \{0, \dots, n\},\\
    \Assign{\prime}{M'}(x) & = 
    \begin{cases}
      x + 1 &\text{if $x < n$}\\
      n &\text{otherwise,}
    \end{cases} \\
    \tuple{x,y} \in \Assign{<}{M'} &\text{iff $x < y$ or $x = y = n$,}
  \end{align*}
  where $n = \max(k,\len{w})$ and $k$~is the least number such that
  $M$ started on input~$w$ has halted after~$k$ steps. We leave the
  verification that $\Sat{M'}{!T'(M,w) \land E(M,w)}$ as an exercise.
\end{proof}

target:
\begin{proof}
  $\Struct{M'}$ د~\olref[ver]{lem:halt-if-valid} په ثبوت کښې د
  جوړښت په شان واخلئ، خو دا توپيرونه ولري:
  \begin{align*}
    \Domain{M'} & = \{0, \dots, n\},\\
    \Assign{\prime}{M'}(x) & =
    \begin{cases}
      x + 1 &\text{که $x < n$ وي}\\
      n &\text{که نۀ وي،}
    \end{cases} \\
    \tuple{x,y} \in \Assign{<}{M'} &\text{هله او يوازې هله چې $x < y$ يا $x = y = n$ وي،}
  \end{align*}
  چې~$n = \max(k,\len{w})$ او~$k$ تر ټولو کوچنی داسې عدد دے چې~$M$
  پر ننوت~$w$ له پيلېدو وروسته له~$k$ ګامونو وروسته درېدلے وي۔ د دې
  خبرې تاييد د تمرين په توګه پرېږدو چې~$\Sat{M'}{!T'(M,w) \land
  !E(M,w)}$۔
  \textbf{د ژباړې د نسخې سمون (OLCMP-067):} سرچينې په وروستي
  پوره-کېدو حکم کښې د درېدنې ټاکلې څيز-ژبې نښه پرېښې وه؛ دلته بشپړه
  جمله راوړل شوې ده۔
\end{proof}

source:
\begin{prob}
  Complete the proof of \olref[tur][und][tra]{lem:halts-sat} by
  proving that $\Sat{M'}{!T(M,w) \land E(M,w)}$.
\end{prob}

\begin{lem}\ollabel{lem:sat-halts}
  If $!T'(M,w) \land !E(M,w)$ has a finite model, then $M$ started on
  input~$w$ halts.
\end{lem}

target:
