source:
\begin{defn}
A set of !!{sentence}s~$\Gamma$ is a \emph{theory} if it is closed
under entailment, i.e., if $\Gamma = \Setabs{!A}{\Gamma \Entails
!A}$.
\end{defn}

target:
\begin{defn}
د !!{sentence}s سټ~$\Gamma$ يوه \emph{تيوري} ده که د لازمې پايلې له
مخې تړلې وي، يعنې که
$\Gamma = \Setabs{!A}{\Gamma \Entails !A}$ وي۔
\end{defn}

source:
\begin{defn}\ollabel{def:standard-model}
The \emph{standard model of arithmetic} is the !!{structure}~$\Struct
N$ defined as follows:
\begin{enumerate}
\item $\Domain N = \Nat$
\item $\Assign{\Obj 0}{N} = 0$
\item $\Assign{\Obj \prime}{N}(n) = n + 1$ for all $n \in \Nat$
\item $\Assign{\Obj +}{N}(n, m) = n + m$ for all $n, m \in \Nat$
\item $\Assign{\Obj \times}{N}(n, m) = n\cdot m$ for all $n, m \in \Nat$
\item $\Assign{\Obj <}{N} = \Setabs{\tuple{n, m}}{n \in \Nat, m \in
  \Nat, n < m}$
\end{enumerate}
\end{defn}

target:
\begin{defn}\ollabel{def:standard-model}
د حساب \emph{معياري مدل} هغه !!{structure}~$\Struct N$ دے چې داسې
تعريفېږي:
\begin{enumerate}
\item $\Domain N = \Nat$
\item $\Assign{\Obj 0}{N} = 0$
\item $\Assign{\Obj \prime}{N}(n) = n + 1$ د ټولو $n \in \Nat$ دپاره
\item $\Assign{\Obj +}{N}(n, m) = n + m$ د ټولو $n, m \in \Nat$ دپاره
\item $\Assign{\Obj \times}{N}(n, m) = n\cdot m$ د ټولو $n, m \in \Nat$ دپاره
\item $\Assign{\Obj <}{N} = \Setabs{\tuple{n, m}}{n \in \Nat, m \in
  \Nat, n < m}$
\end{enumerate}
\end{defn}

source:
\begin{defn}
A theory~$\Gamma$ is \emph{axiomatized} by~$\Gamma_0$ iff
\[
\Gamma = \Setabs{!A}{\Gamma_0 \Entails !A}
\]
\end{defn}

target:
\begin{defn}
تيوري~$\Gamma$ هله او يوازې هله د~$\Gamma_0$ په وسيله بديهي شوې ده
چې
\[
\Gamma = \Setabs{!A}{\Gamma_0 \Entails !A}
\]
\end{defn}

\emph{د پيانو حساب}~$\Th{PA}$ هغه تيوري ده چې د~$\Th{Q}$ په بديهي
اصولو او د استقرا شېما په ټولو بېلګو بديهي شوې ده۔
\end{defn}

source:
\begin{defn}
A theory $\Gamma$ is \emph{!!{complete}} iff for every
!!{sentence}~$!A$ in its language, either $\Gamma \Entails !A$ or
$\Gamma \Entails \lnot !A$.
\end{defn}

target:
\begin{defn}
تيوري~$\Gamma$ هله او يوازې هله \emph{!!{complete}} ده چې د هغې د
ژبې د هرې !!{sentence}~$!A$ دپاره يا~$\Gamma \Entails !A$ يا
$\Gamma \Entails \lnot !A$ وي۔
\end{defn}

source:
\begin{explain}
By the Completeness Theorem, $\Gamma \Entails !A$ iff $\Gamma \Proves
!A$, so $\Gamma$ is complete iff for every !!{sentence}~$!A$ in its
language, either $\Gamma \Proves !A$ or $\Gamma \Proves \lnot !A$.
\end{explain}

target:
\begin{explain}
د بشپړتيا د قضيې له مخې~$\Gamma \Entails !A$ هله او يوازې هله چې
$\Gamma \Proves !A$، نو~$\Gamma$ هله او يوازې هله بشپړه ده چې د
هغې د ژبې د هرې !!{sentence}~$!A$ دپاره يا~$\Gamma \Proves !A$ يا
$\Gamma \Proves \lnot !A$ وي۔
\end{explain}

source:
\begin{defn}
A set $X$ is \emph{!!{decidable}} iff there is a computational procedure
which on input~$x$ returns~$1$ if $x \in X$ and $0$ otherwise.
\end{defn}

target:
\begin{defn}
سټ~$X$ هله او يوازې هله \emph{!!{decidable}} دے چې داسې محاسبوي
کړنلاره وي چې پر ننوت~$x$، که~$x \in X$ وي~$1$ او که نۀ وي~$0$
بېرته ورکوي۔
\end{defn}

source:
\begin{defn}
A theory is \emph{!!{axiomatizable}} if it is axiomatized
by !!a{decidable} set of axioms.
\end{defn}

target:
\begin{defn}
يوه تيوري \emph{!!{axiomatizable}} ده که د بديهي اصولو د
!!a{decidable} سټ په وسيله بديهي شوې وي۔
\end{defn}

source:
\begin{defn}
A set $X$ is called \emph{!!{computably enumerable}} (!!{c.e.} for
short) iff it is empty or it has a computable enumeration.
\end{defn}

target:
\begin{defn}
سټ~$X$ هله او يوازې هله \emph{!!{computably enumerable}} (په لنډ ډول
!!{c.e.}) بلل کېږي چې تش وي يا محاسبه کېدونکې شمېره ولري۔
\end{defn}

source:
\begin{defn}
A !!{formula}~$!A(x_1, \dots, x_k, y)$ \emph{!!{represents}} the
function $f\colon \Nat^k \to \Nat$ in~$\Gamma$ iff whenever $f(n_1,
\dots, n_k) = m$, then
\begin{enumerate}
\item $\Gamma \Proves !A(\num{n_1}, \dots, \num{n_k}, \num{m})$, and
\item $\Gamma \Proves \lforall[y](!A(\num{n_1}, \dots, \num{n_k},
y) \lif y = \num{m})$.
\end{enumerate}
\end{defn}

target:
\begin{defn}
!!{formula}~$!A(x_1, \dots, x_k, y)$ په~$\Gamma$ کښې تابع
$f\colon \Nat^k \to \Nat$ هله او يوازې هله \emph{!!{represents}}
کوي چې هر کله~$f(n_1, \dots, n_k) = m$ وي، نو
\begin{enumerate}
\item $\Gamma \Proves !A(\num{n_1}, \dots, \num{n_k}, \num{m})$، او
\item $\Gamma \Proves \lforall[y](!A(\num{n_1}, \dots, \num{n_k},
y) \lif y = \num{m})$۔
\end{enumerate}
\end{defn}

source:
\begin{defn}
A !!{formula}~$!A(x_1, \dots, x_k)$ \emph{!!{represents}} the
relation $R \subseteq \Nat^k$ iff,
\begin{enumerate}
\item whenever $R(n_1, \dots, n_k)$, $\Gamma \Proves !A(\num{n_1},
\dots, \num{n_k})$, and
\item whenever not $R(n_1, \dots, n_k)$, $\Gamma \Proves \lnot
!A(\num{n_1}, \dots, \num{n_k})$.
\end{enumerate}
\end{defn}

target:
\begin{defn}
!!{formula}~$!A(x_1, \dots, x_k)$ اړيکه~$R \subseteq \Nat^k$ هله او
يوازې هله \emph{!!{represents}} کوي چې
\begin{enumerate}
\item هر کله~$R(n_1, \dots, n_k)$ وي،
$\Gamma \Proves !A(\num{n_1}, \dots, \num{n_k})$، او
\item هر کله~$R(n_1, \dots, n_k)$ نۀ وي،
$\Gamma \Proves \lnot !A(\num{n_1}, \dots, \num{n_k})$۔
\end{enumerate}
\end{defn}

source:
\begin{thm}
If $\Gamma$ is a consistent and !!{axiomatizable} theory in~$\Lang
L_A$ which !!{represents} all computable functions and !!{decidable}
relations, then $\Gamma$ is not !!{complete}.
\end{thm}

target:
\begin{thm}
که~$\Gamma$ په~$\Lang L_A$ کښې داسې سازګاره او !!{axiomatizable}
تيوري وي چې ټولې محاسبه کېدونکې تابعې او ټولې !!{decidable} اړيکې
!!{represents} کوي، نو~$\Gamma$ !!{complete} نۀ ده۔
\end{thm}

source:
\begin{thm}
If $\Gamma$ is a consistent theory that !!{represents} every
!!{decidable} relation, then $\Gamma$ is not !!{decidable}.
\end{thm}

target:
\begin{thm}
که~$\Gamma$ يوه داسې سازګاره تيوري وي چې هره !!{decidable} اړيکه
!!{represents} کوي، نو~$\Gamma$ !!{decidable} نۀ ده۔
\end{thm}

source:
\begin{proof}
Suppose $\Gamma$ were !!{decidable}. We show that if $\Gamma$
!!{represents} every !!{decidable} relation, it must be inconsistent.

target:
\begin{proof}
فرض کړئ~$\Gamma$ !!{decidable} وي۔ ښيو چې که~$\Gamma$ هره
!!{decidable} اړيکه !!{represents} کړي، نو بايد ناسازګاره وي۔

دا پايله د ناتکميلۍ د لومړۍ قضيې د يوې کمزورې بڼې د ترلاسه کولو
دپاره هم کارولے شو۔ هره هغه تيوري چې !!{axiomatizable} او
!!{complete} وي، !!{decidable} ده۔ نو سازګارې تيورۍ چې
!!{axiomatizable} وي او ټول !!{decidable} خاصيتونه !!{represents}
کوي، !!{complete} کېدے نۀ شي۔
\end{explain}

source:
\begin{thm}
If $\Gamma$ is !!{axiomatizable} and !!{complete} it is !!{decidable}.
\end{thm}

target:
\begin{thm}
که~$\Gamma$ !!{axiomatizable} او !!{complete} وي، نو !!{decidable}
ده۔
\end{thm}

source:
\begin{cor}
\ollabel{cor:incompleteness}
If $\Gamma$ is consistent, !!{axiomatizable}, and !!{represents} every
!!{decidable} property, it is not !!{complete}.
\end{cor}

target:
\begin{cor}
\ollabel{cor:incompleteness}
که~$\Gamma$ سازګاره او !!{axiomatizable} وي او هر !!{decidable}
خاصيت !!{represents} کړي، نو !!{complete} نۀ ده۔
\end{cor}

source:
\begin{proof}
If $\Gamma$ were !!{complete}, it would be !!{decidable} by the
previous theorem (since it is !!{axiomatizable} and consistent). But
since $\Gamma$ !!{represents} every !!{decidable} property, it is not
!!{decidable}, by the first theorem.
\end{proof}

target:
\begin{proof}
که~$\Gamma$ !!{complete} وے، د تېرې قضيې له مخې به !!{decidable} وه
(ځکه !!{axiomatizable} او سازګاره ده)۔ خو څرنګه چې~$\Gamma$ هر !!{decidable}
خاصيت !!{represents} کوي، د لومړۍ قضيې له مخې !!{decidable} نۀ ده۔
\end{proof}

source:
