source:
\begin{prop}
The relation $\fn{Atom}(x)$ which holds iff $x$ is the G\"odel number
of an atomic !!{formula}, is primitive recursive.
\end{prop}

target:
\begin{prop}
هغه اړيکه $\fn{Atom}(x)$ چې هله صدق کوي چې $x$ د يوه اټومي
!!{formula} ګوډل شمېره وي، بنسټيزه بازګشتي ده۔
\end{prop}

source:
\begin{proof}
The number $x$ is the G\"odel number of an atomic !!{formula} iff
one of the following holds:
\begin{enumerate}
\item There are $n$, $j < x$, and $z < x$ such that for each $i < n$,
  $\fn{Term}((z)_i)$ and $x = $
\[
\Gn{\Obj P^n_j(} \concat \fn{flatten}(z) \concat \Gn{)}.
\]
\item There are $z_1, z_2 < x$ such that $\fn{Term}(z_1)$,
  $\fn{Term}(z_2)$, and $x = $
\[
\Gn{{\eq}(} \concat z_1 \concat \Gn{,} \concat z_2 \concat{\Gn{)}}.
\]
  \tagitem{prvFalse}{$x = \Gn{\lfalse}$.}{}
  \tagitem{prvTrue}{$x = \Gn{\ltrue}$.}{}
\end{enumerate}
\end{proof}

target:
\begin{proof}
عدد $x$ هله د يوه اټومي !!{formula} ګوډل شمېره ده چې له لاندې څخه
يو حالت صدق وکړي:
\begin{enumerate}
\item داسې $n$، $j<x$ او $z<x$ شته چې د هر $i<n$ دپاره
  $\fn{Term}((z)_i)$ وي او $x = $
\[
\Gn{\Obj P^n_j(} \concat \fn{flatten}(z) \concat \Gn{)}.
\]
\item داسې $z_1,z_2<x$ شته چې $\fn{Term}(z_1)$،
  $\fn{Term}(z_2)$ وي، او $x = $
\[
\Gn{{\eq}(} \concat z_1 \concat \Gn{,} \concat z_2 \concat{\Gn{)}}.
\]
  \tagitem{prvFalse}{$x = \Gn{\lfalse}$۔}{}
  \tagitem{prvTrue}{$x = \Gn{\ltrue}$۔}{}
\end{enumerate}
\end{proof}

