source:
\begin{prop}
  \ollabel{prop:prf-prim-rec}
  Suppose $\Gamma$ is a primitive recursive set of !!{sentence}s.
  Then the relation $\Prf[\Gamma](x, y)$ expressing ``$x$ is the code
  of !!a{derivation}~$\delta$ of $!A$ from !!{undischarged}
  assumptions in~$\Gamma$ and $y$ is the G\"odel number of~$!A$'' is
  primitive recursive.
\end{prop}

target:
\begin{prop}
  \ollabel{prop:prf-prim-rec}
  فرض کړئ $\Gamma$ د !!{sentence}s يو بنسټيز بازګشتي سټ دے۔ بيا
  اړيکه $\Prf[\Gamma](x,y)$، چې وايي «$x$ له~$\Gamma$ کښې
  !!{undischarged} فرضونو څخه د~$!A$ د !!a{derivation}~$\delta$ کوډ
  دے او $y$ د~$!A$ ګوډل شمېره ده»، بنسټيزه بازګشتي ده۔
\end{prop}

source:
  By \olref{prop:deriv}, the property $\fn{Deriv}(x)$ which holds iff
  $x$ is the G\"odel number of a correct !!{derivation}~$\delta$ in
  natural deduction is primitive recursive. Thus we can define
  $\Prf[\Gamma](x, y)$ by
  \begin{align*}
    \Prf[\Gamma](x, y) \defiff {}
    & \fn{Deriv}(x) \land \fn{EndFmla}(x) = y \land {} \\
    & \bforall{z < x}{(\fn{OpenAssum}(z, x) \lif R_\Gamma(z))}.
  \end{align*}
\end{proof}

target:
  د \olref{prop:deriv} له مخې خاصيت $\fn{Deriv}(x)$، چې هله صدق کوي
  چې $x$ په طبيعي استنتاج کښې د يوه سم !!{derivation}~$\delta$ ګوډل
  شمېره وي، بنسټيز بازګشتي دے۔ نو $\Prf[\Gamma](x,y)$ داسې تعريفولے
  شو:
  \begin{align*}
    \Prf[\Gamma](x, y) \defiff {}
    & \fn{Deriv}(x) \land \fn{EndFmla}(x) = y \land {} \\
    & \bforall{z < x}{(\fn{OpenAssum}(z, x) \lif R_\Gamma(z))}.
  \end{align*}
\end{proof}

source:
\begin{explain}
In order to arithmetize axiomatic !!{derivation}s, we must represent
!!{derivation}s as numbers. Since !!{derivation}s are simply sequences
of !!{formula}s, the obvious approach is to code every !!{derivation}
as the code of the sequence of codes of !!{formula}s in it.
\end{explain}

target:
\begin{explain}
د بديهي !!{derivation}s د حسابي کولو دپاره بايد !!{derivation}s د
عددونو په توګه تمثيل کړو۔ ځکه چې !!{derivation}s يوازې د
!!{formula}s لړۍ دي، نو څرګنده لار دا ده چې هر !!{derivation} د هغه
د !!{formula}s د کوډونو د لړۍ په کوډ سره کوډ کړو۔
\end{explain}

source:
\begin{ex}
  Consider the very simple !!{derivation}:
  \begin{derivation}
  1. & $!B \lif (!B \lor !A)$ \\
  2. & $(!B \lif (!B \lor !A)) \lif (!A  \lif (!B \lif (!B \lor !A)))$\\
  3. & $!A  \lif (!B \lif (!B \lor !A))$
  \end{derivation}
  The G\"odel number of this !!{derivation} would be
  \begin{align*}
  \openTuple\, 
    & \Gn{!B \lif (!B \lor !A)}, \\
    &\Gn{(!B \lif (!B \lor !A)) \lif (!A  \lif (!B \lif (!B \lor !A)))},\\
    & \Gn{!A  \lif (!B \lif (!B \lor !A))} \,\closeTuple.
  \end{align*}
\end{ex}

target:
\begin{ex}
  دا ډېر ساده !!{derivation} وګورئ:
  \begin{derivation}
  1. & $!B \lif (!B \lor !A)$ \\
  2. & $(!B \lif (!B \lor !A)) \lif (!A  \lif (!B \lif (!B \lor !A)))$\\
  3. & $!A  \lif (!B \lif (!B \lor !A))$
  \end{derivation}
  د دې !!{derivation} ګوډل شمېره به دا وي:
  \begin{align*}
  \openTuple\,
    & \Gn{!B \lif (!B \lor !A)}, \\
    &\Gn{(!B \lif (!B \lor !A)) \lif (!A  \lif (!B \lif (!B \lor !A)))},\\
    & \Gn{!A  \lif (!B \lif (!B \lor !A))} \,\closeTuple.
  \end{align*}
\end{ex}

