\begin{prop}
\ollabel{prop:followsby}
The following relations are primitive recursive:
\begin{enumerate}
\item $!A$ is an axiom.
\item The $i$-th line in $\delta$ is justified by modus ponens
\item The $i$-th line in $\delta$ is justified by \QR.
\item $\delta$ is a correct !!{derivation}.
\end{enumerate}
\end{prop}

target:
\begin{prop}
\ollabel{prop:followsby}
لاندې اړيکې بنسټيزې بازګشتي دي:
\begin{enumerate}
\item $!A$ يو بديهي اصل دے۔
\item په~$\delta$ کښې $i$-مه کرښه په مودوس پوننس توجيه شوې ده۔
\item په~$\delta$ کښې $i$-مه کرښه په \QR{} توجيه شوې ده۔
\item $\delta$ يو سم !!{derivation} دے۔
\end{enumerate}
\end{prop}

