\ollabel{prop:rep-proj}
The projection function $\Proj{n}{i}(x_0, \dots, x_{n-1}) = x_i$ is
represented in~$\Th{Q}$ by \[!A_{\Proj{n}{i}}(x_0, \dots, x_{n-1}, y) \ident \eq[y][x_i].\]
\end{prop}

target:
