\begin{prop}
\ollabel{prop:rep-minimization}
If $!A_g(x, z, y)$ represents $g(x, z)$ in~$\Th{Q}$, then
\[
!A_f(z,y) \ident !A_g(y, z, \Obj 0) \land \lforall[w][(w < y \lif \lnot
  !A_g(w, z, \Obj 0))]
\]
represents $f(z) = \umin{x}{[g(x, z) = 0]}$.
\end{prop}

target:
