source:
\begin{defn}[Variable Assignment]
A \emph{variable assignment}~$s$ for !!a{structure}~$\Struct{M}$ is a
function which maps each
\begin{enumerate}
\item object !!{variable}~$\Obj{v_i}$ to an element of~$\Domain M$,
  i.e., $s(\Obj{v_i}) \in \Domain{M}$
\item $n$-place relation variable~$\Obj{V_i^n}$ to an $n$-place
  relation on~$\Domain{M}$, i.e., $s(\Obj{V_i^n}) \subseteq \Domain{M}^n$;
\item $n$-place function variable~$\Obj{u_i^n}$ to an $n$-place
  function from $\Domain{M}$ to $\Domain{M}$, i.e.,
  $s(\Obj{u_i^n})\colon \Domain{M}^n \to \Domain{M}$;
\end{enumerate}
\end{defn}

\begin{explain}
!!^a{structure} assigns !!a{value} to each !!{constant} and
!!{function}, and a second-order variable assignment assigns objects and
functions to each object and function variable. Together, they let us
assign a value to every term.
\end{explain}

target:
\begin{explain}
!!^a{structure} هر !!{constant} او !!{function} ته !!a{value}
ورکوي، او د دويمې درجې د متغير ګومارنه د هر څيز او تابع متغير دپاره
څيزونه او تابعې ټاکي۔ دواړه په ګډه هر ترم ته يو ارزښت ټاکلو ته لار
هواروي۔
\end{explain}

source:
\begin{defn}[\usetoken{S}{value} of a Term]
If $t$ is a term of the language~$\Lang L$, $\Struct M$ is
!!a{structure} for~$\Lang L$, and $s$ is !!a{variable} assignment
for~$\Struct M$, the \emph{!!{value}}~$\Value{t}{M}[s]$ is defined as
for first-order terms, plus the following clause:
\begin{quote}
\indcase{t}{\Atom{u}{t_1, \ldots, t_n}}{
\[
\Value{\indfrm}{M}[s] = s(u)(\Value{t_1}{M}[s], \ldots,
\Value{t_n}{M}[s]).
\]}
\end{quote}
\end{defn}

target:
\begin{defn}[د ترم \usetoken{S}{value}]
که $t$ د ژبې~$\Lang L$ يو ترم، $\Struct M$ د~$\Lang L$ يو
!!a{structure}، او $s$ د~$\Struct M$ دپاره !!a{variable} ګومارنه
وي، \emph{!!{value}}~$\Value{t}{M}[s]$ د لومړۍ درجې ترمونو په څېر
تعريفېږي، له لاندې اضافي شرط سره:
\begin{quote}
\indcase{t}{\Atom{u}{t_1, \ldots, t_n}}{
\[
\Value{\indfrm}{M}[s] = s(u)(\Value{t_1}{M}[s], \ldots,
\Value{t_n}{M}[s]).
\]}
\end{quote}
\end{defn}

source:
\begin{defn}[Satisfaction]
For second-order !!{formula}s~$!A$, the definition of satisfaction is
like \olref[fol][syn][sat]{defn:satisfaction} with the addition of:
\begin{enumerate}
\item \indcase{!A}{\Atom{X^n}{t_1, \dots, t_n}}{$\Sat{M}{\indfrm}[s]$
  iff $\langle \Value{t_1}{M}[s], \dots, \Value{t_n}{M}[s] \rangle \in
  s(X^n)$.}
\tagitem{prvAll}{%
  \indcase{!A}{\lforall[X][!B]}{$\Sat{M}{\indfrm}[s]$ iff for every $M
  \subseteq \Domain{M}^n$, $\Sat{M}{!B}[\Subst{s}{M}{X}]$.}}{}

\tagitem{prvEx}{%
  \indcase{!A}{\lexists[u][!B]}{$\Sat{M}{\indfrm}[s]$ iff for at least
  one $f\colon \Domain{M}^n \to \Domain{M}$ so that
  $\Sat{M}{!B}[\Subst{s}{f}{u}]$.}}{}
\end{enumerate}
\end{defn}

target:
\tagitem{prvEx}{%
  \indcase{!A}{\lexists[u][!B]}{$\Sat{M}{\indfrm}[s]$ هله او يوازې
  هله چې لږ تر لږه د يوې $f\colon \Domain{M}^n \to \Domain{M}$ دپاره
  $\Sat{M}{!B}[\Subst{s}{f}{u}]$ وي۔}}{}
\end{enumerate}
\end{defn}

source:
\begin{prob}
  Show that in second-order logic $\lforall$ and~$\lif$ can define the other
  connectives:
  \begin{enumerate}
    \item Prove that in second-order logic $!A \land !B$ is equivalent
    to $\lforall[X][(!A \lif (!B \lif \lforall[x][X(x)])\lif
    \lforall[x][X(x)])]$.
    \item Find a second-order formula using only $\lforall$ and $\lif$
    equivalent to $!A \lor !B$.
  \end{enumerate}
\end{prob}

target:
\begin{prob}
  وښيئ چې په دويمې درجې منطق کښې $\lforall$ او~$\lif$ نور
  نښلوونکي تعريفولے شي:
  \begin{enumerate}
    \item ثابته کړئ چې په دويمې درجې منطق کښې $!A \land !B$ له
    $\lforall[X][(!A \lif (!B \lif \lforall[x][X(x)])\lif
    \lforall[x][X(x)])]$ سره معادل دے۔
    \item داسې د دويمې درجې فارمولا ومومئ چې يوازې $\lforall$ او
    $\lif$ کاروي او له $!A \lor !B$ سره معادله وي۔
  \end{enumerate}
\emph{سرچينه‌يي يادونه OLSOL-014: په لومړي تمرين کښې د بهرني کمیت ټاکونکي اړيکيز متغير بايد نوے وي، يعنې د دواړو ورکړل شويو فارمولونو ازادې پېښې ونۀ نيسي۔ له دې قيد پرته چاپي ښودنه د هغو فارمولونو مانا بدلولے شي۔ د يوه غړي په ساحه کښې که دواړه فارمولونه د همدغه متغير د هغه غړي خاصيت وي، د ټولې ساحې په ګومارنه دواړه رښتيا دي، خو د چاپي ښودنې بهرنے عمومي کمیت ټاکونکے تشه اړيکه هم اخلي او پايله دروغ کوي۔ د نوې نښې په ټاکلو د عطف مطلوب تعريف سم دے۔ اصلي ښودنه ساتل شوې ده۔}
\end{prob}

\begin{defn}
که $\Struct{M}$ د ژبې~$\Lang{L}$ يو !!a{structure} وي، اړيکه
$R \subseteq \Domain{M}^2$ هله په~$\Lang{L}$ کښې \emph{تعريفېدونکې}
ده چې داسې !!{formula}~$!A_R(x, y)$ وي چې يوازې $x$ او~$y$ يې ازاد
متغيرونه وي، او $R(a, b)$، يعنې $\tuple{a,b} \in R$، هله او يوازې
هله برقرار وي چې د $s(x) = a$ او $s(y) = b$ دپاره
$\Sat{M}{!A_R(x, y)}[s]$ وي۔
\end{defn}

