source:
\begin{thm}
\ollabel{thm:sol-pa-standard}
If $\Sat{M}{\Th{PA^2}}$ then $\Domain{M} =
\Setabs{\Value{\num{n}}{M}}{n \in \Nat}$.
\end{thm}

target:
\begin{thm}
\ollabel{thm:sol-pa-standard}
که $\Sat{M}{\Th{PA^2}}$، نو $\Domain{M} =
\Setabs{\Value{\num{n}}{M}}{n \in \Nat}$.
\end{thm}

source:
We have that $\Sat{M}{X(\Obj 0) \land \lforall[x][(X(x) \lif X(x'))]}[s]$.
Consequently, $\Sat{M}{\lforall[x][X(x)]}[s]$. But that means that for
every $x \in \Domain{M}$ we have $x \in s(X) = N$. So, $\Domain{M}
\subseteq N$.
\end{proof}

target:
نو $\Sat{M}{X(\Obj 0) \land \lforall[x][(X(x) \lif X(x'))]}[s]$ لرو۔
له دې امله $\Sat{M}{\lforall[x][X(x)]}[s]$۔ دا وايي چې د هر
$x \in \Domain{M}$ دپاره $x \in s(X) = N$؛ نو $\Domain{M}
\subseteq N$۔
\end{proof}

source:
\begin{cor}
\ollabel{cor:sol-pa-categorical}
Any two models of~$\Th{PA^2}$ are isomorphic.
\end{cor}

target:
\begin{cor}
\ollabel{cor:sol-pa-categorical}
د~$\Th{PA^2}$ هر دوه مدلونه آيزومورف دي۔
\end{cor}

source:
\begin{proof}
By \olref{thm:sol-pa-standard}, the domain of any model of $\Th{PA^2}$
is exhausted by $\Value{\num{n}}{M}$. Any such model is also a model
of~$\Th{Q}$. By \olref[mod][mar][stm]{prop:thq-standard}, any such
model is standard, i.e., isomorphic to~$\Struct{N}$.
\end{proof}

target:
\begin{proof}
د \olref{thm:sol-pa-standard} له مخې، د~$\Th{PA^2}$ د هر مدل تعريف ساحه
د~$\Value{\num{n}}{M}$ له ارزښتونو پرته بل څه نۀ لري۔ هر داسې مدل
د~$\Th{Q}$ مدل هم دے۔ د \olref[mod][mar][stm]{prop:thq-standard} له
مخې، هر داسې مدل معياري دے؛ يعنې له~$\Struct{N}$ سره آيزومورف دے۔
\end{proof}

source:
\begin{prop}\ollabel{prop:sol-pa-definable}
Let $\Th{PA^{2\dagger}}$ be the second-order theory containing the
first two arithmetical axioms (the successor axioms) and the
second-order induction axiom. Then $\le$, $+$, and $\times$ are definable
in $\Th{PA^{2\dagger}}$.
\end{prop}

target:
\begin{prop}\ollabel{prop:sol-pa-definable}
دې $\Th{PA^{2\dagger}}$ هغه د دويمې درجې تيوري وي چې لومړني دوه
حسابي بديهي اصول (د جانشين بديهي اصول) او د دويمې درجې د استقرا
بديهي اصل لري۔ نو $\le$، $+$ او $\times$ په~$\Th{PA^{2\dagger}}$
کښې تعريفېدے شي۔
\end{prop}

source:
\begin{prob}
Complete the proof of \olref[sol][met][spa]{prop:sol-pa-definable}.
\end{prob}

target:
\begin{prob}
د \olref[sol][met][spa]{prop:sol-pa-definable} ثبوت بشپړ کړئ۔
