source:
\begin{conv}
\begin{enumerate}
\item When parentheses are left out, application takes place from left
  to right. For example, if $M$, $N$, $P$, and $Q$ are terms, then
  $MNPQ$ abbreviates $(((MN)P)Q)$.
\item Again, when parentheses are left out, lambda abstraction is to
  be given the widest scope possible. From example, $\lambd[x][MNP]$ is
  read $(\lambd[x][((MN)P)])$.
\item A lambda can be used to abstract multiple variables. For
  example, $\lambd[xyz][M]$ is short for
  $\lambd[x][\lambd[y][\lambd[z][M]]]$.
\end{enumerate}
\end{conv}

target:
\begin{conv}
\begin{enumerate}
\item چې قوسونه پرېښودل شي، تطبيق له کيڼ لوري ښي لوري ته ترسره کېږي۔
  مثلاً، که $M$، $N$، $P$ او $Q$ ترمونه وي، نو $MNPQ$ د
  $(((MN)P)Q)$ لنډه بڼه ده۔
\item همداسې، چې قوسونه پرېښودل شي، لامبډا تجريد ته تر وسه پراخه
  ساحه ورکوو۔ مثلاً، $\lambd[x][MNP]$ د
  $(\lambd[x][((MN)P)])$ په معنا لولو۔
\item يوه لامبډا د څو متغيرونو د تجريد دپاره کارېدے شي۔ مثلاً،
  $\lambd[xyz][M]$ د
  $\lambd[x][\lambd[y][\lambd[z][M]]]$ لنډه بڼه ده۔
\end{enumerate}
\end{conv}

