source:
\begin{defn}[Change of bound variable, $\aconvone$] \ollabel{defn:aconvone}
  \emph{Change of bound variable} ($\aconvone$) is inductively
  defined as follows:
  \begin{enumerate}
  \item If $N \aconvone N'$ then $\lambd[x][N] \aconvone
    \lambd[x][N']$ \ollabel{defn:aconvone1}
  \item If $P \aconvone P'$ then $(PQ) \aconvone (P'Q)$ \ollabel{defn:aconvone2}
  \item If $Q \aconvone Q'$ then $(PQ) \aconvone (PQ')$ \ollabel{defn:aconvone3}
  \item If $x \neq y$, $y \notin \FV{N}$ and $\Subst{N}{y}{x}$ is defined, then
    $\lambd[x][N] \redone[\alpha] \lambd[y][\Subst{N}{y}{x}]$.
    \ollabel{defn:aconvone4}
  \end{enumerate}
\end{defn}

target:
\begin{defn}[د تړلي متغير د نوم بدلون، $\aconvone$] \ollabel{defn:aconvone}
  \emph{د تړلي متغير د نوم بدلون} ($\aconvone$) په استقرايي
  ډول داسې تعريفېږي:
  \begin{enumerate}
  \item که $N \aconvone N'$ وي، نو $\lambd[x][N] \aconvone
    \lambd[x][N']$ وي۔ \ollabel{defn:aconvone1}
  \item که $P \aconvone P'$ وي، نو $(PQ) \aconvone (P'Q)$ وي۔ \ollabel{defn:aconvone2}
  \item که $Q \aconvone Q'$ وي، نو $(PQ) \aconvone (PQ')$ وي۔ \ollabel{defn:aconvone3}
  \item که $x \neq y$، $y \notin \FV{N}$ او $\Subst{N}{y}{x}$
    ټاکلے وي، نو
    $\lambd[x][N] \redone[\alpha] \lambd[y][\Subst{N}{y}{x}]$ وي۔
    \ollabel{defn:aconvone4}
  \end{enumerate}
\end{defn}

source:
\begin{defn}[$\alpha$-conversion, $\aconv$] \ollabel{defn:aconv}
  \emph{$\alpha$-conversion} ($\aconv$) is inductively defined as follows:
  \begin{enumerate}
  \item If $P \aconv Q$ and $Q \aconv R$, then $P \aconv R$.
    \ollabel{defn:aconv1}
  \item If $P \aconvone Q$, then $P \aconv Q$. \ollabel{defn:aconv2}
  \item $P \aconv P$. \ollabel{defn:aconv3}
  \end{enumerate}
\end{defn}

target:
\begin{defn}[$\alpha$-بدلون، $\aconv$] \ollabel{defn:aconv}
  \emph{$\alpha$-بدلون} ($\aconv$) په استقرايي ډول داسې
  تعريفېږي:
  \begin{enumerate}
  \item که $P \aconv Q$ او $Q \aconv R$ وي، نو $P \aconv R$ وي۔
    \ollabel{defn:aconv1}
  \item که $P \aconvone Q$ وي، نو $P \aconv Q$ وي۔ \ollabel{defn:aconv2}
  \item $P \aconv P$. \ollabel{defn:aconv3}
  \end{enumerate}
\end{defn}

