\begin{defn}[$\beta\eta$-complete development]\ollabel{defn:becd}
  The \emph{$\beta\eta$-complete development}~$\becd{M}$ of~$M$ is defined
  as follows:
  \begin{align}
    \becd{x} &= x \ollabel{defn:becd1} \\
    \becd{(\lambd[x][N])} &= \lambd[x][\becd{N}] \ollabel{defn:becd2}\\
    \becd{(PQ)} &= \becd{P}\becd{Q} && \text{if $P$ is not a $\lambd$-abstract} 
    \ollabel{defn:becd3} \\
    \becd{((\lambd[x][N])Q)} &= \Subst{\becd{N}}{\becd{Q}}{x}
                             \ollabel{defn:becd4} \\
    \becd{(\lambd[x][Nx])} &= \becd{N} \ollabel{defn:becd5} & \text{if $x
                                                      \notin FV(N)$}
  \end{align}
\end{defn}

target:
\begin{defn}[$\beta\eta$-بشپړ راکمول]\ollabel{defn:becd}
  د~$M$ \emph{$\beta\eta$-بشپړ راکمول}~$\becd{M}$ داسې
  تعريفېږي:
  \begin{align}
    \becd{x} &= x \ollabel{defn:becd1} \\
    \becd{(\lambd[x][N])} &= \lambd[x][\becd{N}] \ollabel{defn:becd2}\\
    \becd{(PQ)} &= \becd{P}\becd{Q} && \text{که $P$ د $\lambd$ تجريد نۀ وي} 
    \ollabel{defn:becd3} \\
    \becd{((\lambd[x][N])Q)} &= \Subst{\becd{N}}{\becd{Q}}{x}
                             \ollabel{defn:becd4} \\
    \becd{(\lambd[x][Nx])} &= \becd{N} \ollabel{defn:becd5} & \text{که $x
                                                      \notin FV(N)$ وي}
  \end{align}
  \textbf{د سرچينې سپيناوی (OLLAM-042):} د تجريد عمومي
  قاعده او وروستۍ د اېټا قاعده د شرط په پوره کېدو يوې بڼې
