source:
\begin{defn}
  A \emph{propositional language} consists of a set $\Lang L$ of
  \emph{connectives}. Each connective $\star$ has an \emph{arity}; a
  connective of arity~$n$ is said to be \emph{$n$-place.}
  Connectives of arity~$0$ are also called \emph{constants};
  connectives of arity~$1$ are called \emph{unary}, and connectives of
  arity~$2$, \emph{binary}.
\end{defn}

\begin{defn}[Matrix]
\ollabel{defn:matrix}
A \emph{matrix} for the logic~$\Log L$ consists of:
\begin{enumerate}
\item a set of connectives making up a language~$\Lang L$;
\item a set $V \neq \emptyset$ of truth values;
\item a set $V^+ \subseteq V$ of designated truth values;
\item for each $n$-place connective $\star$ in $\Lang L$, a truth
function~$\tf{\star} : V^n \to V$. If $n = 0$, then $\tf{\star}$ is
just an element of~$V$.
\end{enumerate}
\end{defn}

target:
\begin{defn}[ماتريس]
\ollabel{defn:matrix}
د منطق~$\Log L$ يو \emph{ماتريس} له لاندې توکو جوړ وي:
\begin{enumerate}
\item د نښلوونکو يو سټ چې ژبه~$\Lang L$ جوړوي؛
\item د رښتياوالي د قيمتونو يو ناتش سټ~$V \neq \emptyset$؛
\item د ټاکل شوو رښتياوالي قيمتونو يو سټ~$V^+ \subseteq V$؛
\item په~$\Lang L$ کښې د هر $n$-ځايه نښلوونکي~$\star$
دپاره د صدق تابعه~$\tf{\star} : V^n \to V$۔ که~$n = 0$
وي، نو~$\tf{\star}$ يوازې د~$V$ يو غړے وي۔
\end{enumerate}
\end{defn}

source:
\begin{ex}
The matrix for classical logic~\LogCL{} consists of:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lfalse$, $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V = \{\True, \False\}$.
  \item $\True$ is the only designated value, i.e., $V^+ = \{\True\}$.
  \item For $\lfalse$, we have $\tf{\lfalse} = \False$. The other
  truth functions are given by the usual truth tables (see
  \olref{fig:tf-CL}).
\end{enumerate}
\begin{figure}
  \begin{center}
      \begin{tabular}{c|c} 
        $\tf{\lnot}$ & \\ 
        \hline  
        $\True$ & $\False$ \\ 
        $\False$ & $\True$ 
      \end{tabular}
      \quad
      \begin{tabular}{c|cc} 
        $\tf{\land}$ & $\True$ & $\False$ \\ 
        \hline 
        $\True$ & $\True$ & $\False$ \\ 
        $\False$ & $\False$ & $\False$ 
      \end{tabular}
      \quad
      \begin{tabular}{c|cc} 
        $\tf{\lor}$ & $\True$ & $\False$ \\ 
        \hline 
        $\True$ & $\True$ & $\True$ \\ 
        $\False$ & $\True$ & $\False$ 
      \end{tabular}
      \quad
      \begin{tabular}{c|cc} 
        $\tf{\lif}$ & $\True$ & $\False$ \\ 
        \hline 
        $\True$ & $\True$ & $\False$ \\ 
        $\False$ & $\True$ & $\True$ 
      \end{tabular}
    \end{center} 
    \caption{Truth functions for classical logic~$\LogCL$.}
    \ollabel{fig:tf-CL}
  \end{figure}
  \end{ex}

target:
\begin{ex}
د کلاسيک منطق~\LogCL{} ماتريس له لاندې توکو جوړ وي:
