\begin{defn}\ollabel{defn:pValue}
  Given !!a{valuation}~$\pAssign{v}$ into the set of truth values~$V$ of a
  many-valued logic~$\Log L$, define the evaluation function
  $\pValue{v} \colon \Frm[L] \to V$ inductively by:
  \begin{enumerate}
    \item $\pValue{v}(\Obj p_n) = \pAssign{v}(\Obj p_n)$; 
    \item If $\star$ is a $0$-place connective, then $\pValue{v}(\star)  = \tf{\star}[\Log L]$;
    \item If $\star$ is an $n$-place connective, then 
    \[
      \pValue{v}(\star(!A_1, \dots, !A_n)) = \tf{\star}[\Log L]
      (\pValue{v}(!A_1), \dots, \pValue{v}(!A_n)).
    \]
  \end{enumerate}
\end{defn}

\begin{defn} 
\begin{enumerate}
\item !!^a{formula}~$!A$ is \emph{satisfiable} if for
  some~$\pAssign{v}$, $\pSat{v}{!A}$; it is
  \emph{unsatisfiable} if for no $\pAssign{v}$, $\pSat{v}{!A}$;
\item !!^a{formula}~$!A$ is a \emph{tautology} if $\pSat{v}{!A}$ for
  all !!{valuation}s~$v$;
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma \Entails !A$ (``$\Gamma$
  entails $!A$'') if and only if $\pSat{v}{!A}$ for every
  !!{valuation}~$\pAssign{v}$ for which $\pSat{v}{\Gamma}$.
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma$ is
  \emph{satisfiable} if there is !!a{valuation}~$\pAssign{v}$ for which
  $\pSat{v}{\Gamma}$, and $\Gamma$ is
  \emph{unsatisfiable} otherwise.
\end{enumerate} 
\end{defn}

\begin{prop}
\ollabel{prop:semanticalfacts} 
\begin{enumerate} 
\item $!A$ is a tautology if and only if
  $\emptyset \Entails !A$; 
\item If $\Gamma$ is satisfiable then every finite subset of $\Gamma$
  is also satisfiable; 
\item\ollabel{def:monotonicity}%
Monotonicity: if $\Gamma \subseteq \Delta$
  and $\Gamma \Entails !A$ then also $\Delta \Entails !A$;
\item\ollabel{def:Cut}%
Transitivity: if $\Gamma \Entails !A$ and
  $\Delta \cup \{ !A\} \Entails !B$ then $\Gamma \cup \Delta \Entails
  !B$;
\end{enumerate}
\end{prop}

target:
\begin{prop}
\ollabel{prop:semanticalfacts}
\begin{enumerate}
\item $!A$ هله او يوازې هله تاوتولوژي ده چې
  $\emptyset \Entails !A$ وي؛
\item که~$\Gamma$ د صدق وړ وي، نو د~$\Gamma$ هر متناهي فرعي سټ
  هم د صدق وړ دے؛
\item\ollabel{def:monotonicity}%
يکنواختي: که $\Gamma \subseteq \Delta$
  او $\Gamma \Entails !A$ وي، نو $\Delta \Entails !A$ هم؛
\item\ollabel{def:Cut}%
انتقاليت: که $\Gamma \Entails !A$ او
  $\Delta \cup \{ !A\} \Entails !B$ وي، نو $\Gamma \cup \Delta \Entails
  !B$؛
\end{enumerate}
\end{prop}

