\begin{proof}
  We prove the contrapositive. Suppose $\Gamma \Entails/[\LogCL] !B$.
  Then there is some !!{valuation}~$\pAssign v\colon \PVar \to
  \{\True, \False\}$ such that $\pValue v[\LogCL](!A) = \True$ for all
  $!A \in \Gamma$ and $\pValue v[\LogCL](!B) = \False$. Since $\True,
  \False \in V$, the !!{valuation}~$\pAssign v$ is also !!a{valuation}
  for~$\Log L$. By \olref{prop:mvl-cl}, $\pValue v[\Log L](!A) =
  \True$ for all $!A \in \Gamma$ and $\pValue v[\Log L](!B) = \False$.
  Since $\True \in V^+$ and $\False \notin V^+$ that means $\pAssign v
  \Entails[\Log L] \Gamma$ and $\pAssign v \Entails/[\Log L] !B$,
  i.e., $\Gamma \Entails/[\Log L] !B$.
\end{proof}
\end{document}

\begin{defn}\ollabel{def:lukasiewicz}
Three-valued \L ukasiewicz logic is defined using the matrix:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V = \{\True, \Undef, \False\}$.
  \item $\True$ is the only designated value, i.e., $V^+ = \{\True\}$.
  \item Truth functions are given by the following tables:
  \begin{center}
    \begin{tabular}{c|c} 
      $\tf{\lnot}$ & \\ 
      \hline  
      $\True$ & $\False$ \\ 
      $\Undef$ & $\Undef$ \\
      $\False$ & $\True$ 
    \end{tabular}
    \quad
    \begin{tabular}{c|ccc} 
      $\tf{\land}[\LogLuk[3]]$ & $\True$ & $\Undef$ & $\False$ \\ 
      \hline 
      $\True$ & $\True$ & $\Undef$ & $\False$ \\ 
      $\Undef$ & $\Undef$ & $\Undef$ & $\False$\\ 
      $\False$ & $\False$ & $\False$ & $\False$ 
    \end{tabular}
    \\[2ex]
    \begin{tabular}{c|ccc} 
      $\tf{\lor}[\LogLuk[3]]$ & $\True$ & $\Undef$ & $\False$ \\ 
      \hline 
      $\True$ & $\True$ & $\True$ & $\True$ \\ 
      $\Undef$ & $\True$ & $\Undef$ & $\Undef$ \\
      $\False$ & $\True$ & $\Undef$ & $\False$ 
    \end{tabular}
    \quad
    \begin{tabular}{c|ccc} 
      $\tf{\lif}[\LogLuk[3]]$ & $\True$ & $\Undef$ & $\False$ \\ 
      \hline 
      $\True$ & $\True$ & $\Undef$ & $\False$ \\ 
      $\Undef$ & $\True$ & $\True$ & $\Undef$  \\ 
      $\False$ & $\True$ & $\True$ & $\True$ 
    \end{tabular}
  \end{center} 
\end{enumerate}
\end{defn}

