\begin{prob}
  Which of the following relations hold in \L ukasiewicz logic? Give a truth table for each.
  \begin{enumerate}
    \item $p, p \lif q \Entails q$
    \item $\lnot\lnot p \Entails p$
    \item $p \land q \Entails p$
    \item $p \Entails p \land p$
    \item $p \Entails p \lor q$
  \end{enumerate}
\end{prob}

target:
\begin{prob}
  لاندې کومې اړيکې د لوکاشېوېچ په منطق کښې صدق کوي؟ د هرې
  يوې دپاره د رښتياوالي جدول ورکړئ۔
  \begin{enumerate}
    \item $p, p \lif q \Entails q$
    \item $\lnot\lnot p \Entails p$
    \item $p \land q \Entails p$
    \item $p \Entails p \land p$
    \item $p \Entails p \lor q$
