source:
\begin{defn}\ollabel{def:goedel} Infinite-valued G\"odel
logic~$\LogGod[\infty]$ is defined using the matrix:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lfalse$, $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V_\infty$.
  \item $1$ is the only designated value, i.e., $V^+ = \{1\}$.
  \item Truth functions are given by the following functions:
  \begin{align*}
    \tf{\lfalse} & = 0\\
    \tf{\lnot}[\LogGod](x) & = \begin{cases}
      $1$ & \text{if } x =0\\
      $0$ & \text{otherwise}
    \end{cases}\\
    \tf{\land}[\LogGod](x,y) & = \min(x,y)\\
    \tf{\lor}[\LogGod](x,y) & = \max(x,y)\\
    \tf{\lif}[\LogGod](x,y) & = \begin{cases}
      1 & \text{if } x \le y\\
      y & \text{otherwise.}
    \end{cases}
    \end{align*}
\end{enumerate}
$m$-valued G\"odel logic is defined the same, except $V = V_m$.
\end{defn}

target:
\begin{defn}\ollabel{def:goedel} نامتناهي ارزښته د ګوډل
منطق~$\LogGod[\infty]$ په دې ماتريس تعريفېږي:
\begin{enumerate}
  \item معياري بياني ژبه~$\Lang L_0$ چې
  $\lfalse$, $\lnot$, $\land$, $\lor$, $\lif$ لري۔
  \item د رښتياوالي د قيمتونو سټ~$V_\infty$۔
  \item يوازې~$1$ ټاکل شوے قيمت دے؛ يعنې~$V^+ = \{1\}$۔
  \item صدق تابعې په لاندې تابعو ټاکل کېږي:
  \begin{align*}
    \tf{\lfalse} & = 0\\
    \tf{\lnot}[\LogGod](x) & = \begin{cases}
      1 & \text{که } x =0\\
      0 & \text{په بل حالت کښې}
    \end{cases}\\
    \tf{\land}[\LogGod](x,y) & = \min(x,y)\\
    \tf{\lor}[\LogGod](x,y) & = \max(x,y)\\
    \tf{\lif}[\LogGod](x,y) & = \begin{cases}
      1 & \text{که } x \le y\\
      y & \text{په بل حالت کښې.}
    \end{cases}
    \end{align*}
  د سرچينې يادونه: اصلي متن د پورته نفي د دوو پايلو شاوخوا د رياضي
  دننه يو ځل بيا د رياضي د پيل او پای نښې ږدي؛ دلته هغه اضافي نښې
  لرې شوې، خو دواړه عددي قيمتونه هماغه پاتې دي۔
\end{enumerate}
د ګوډل $m$-ارزښته منطق همداسې تعريفېږي، خو~$V = V_m$ لري۔
\end{defn}

source:
\begin{prop}
  The logic $\LogGod[3]$ defined by \olref[thr][god]{defn:goedel}
  is the same as $\LogGod[3]$ defined by \olref{def:goedel}.
\end{prop}

target:
\begin{prop}
  د~\olref[thr][god]{defn:goedel} له مخې تعريف شوے منطق~$\LogGod[3]$
  د~\olref{def:goedel} له مخې له تعريف شوي~$\LogGod[3]$ سره يو شان دے۔
\end{prop}

source:
\begin{proof}
  This can be seen by comparing the truth tables for the connectives
  given in \olref[thr][god]{defn:goedel} with the truth tables
  determined by the equations in \olref{def:goedel}:
  \begin{center}
    \begin{tabular}{c|c} 
      $\tf{\lnot}[\LogGod[3]]$ & \\ 
      \hline  
      $1$ & $0$ \\ 
      $1/2$ & $0$ \\
      $0$ & $1$ 
    \end{tabular}
    \quad
    \begin{tabular}{c|ccc} 
      $\tf{\land}[\LogGod]$ & $1$ & $1/2$ & $0$ \\ 
      \hline 
      $1$ & $1$ & $1/2$ & $0$ \\ 
      $1/2$ & $1/2$ & $1/2$ & $0$\\ 
      $0$ & $0$ & $0$ & $0$ 
    \end{tabular}
    \\[2ex]
    \begin{tabular}{c|ccc} 
      $\tf{\lor}[\LogGod]$ & $1$ & $1/2$ & $0$ \\ 
      \hline 
      $1$ & $1$ & $1$ & $1$ \\ 
      $1/2$ & $1$ & $1/2$ & $1/2$ \\
      $0$ & $1$ & $1/2$ & $0$ 
    \end{tabular}
    \quad
    \begin{tabular}{c|ccc} 
      $\tf{\lif}[\LogGod]$ & $1$ & $1/2$ & $0$ \\ 
      \hline 
      $1$ & $1$ & $1/2$ & $0$ \\ 
      $1/2$ & $1$ & $1$ & $0$  \\ 
      $0$ & $1$ & $1$ & $1$ 
    \end{tabular}
  \end{center} 
\end{proof}

