\begin{defn}
  A \emph{model} for the basic modal language is a triple $\mModel{M}
  = \tuple{W, R, V}$, where
  \begin{enumerate}
  \item $W$ is a nonempty set of ``worlds,''
  \item $R$ is a binary accessibility relation on~$W$, and
  \item $V$ is a function assigning to each !!{propositional
    variable}~$p$ a set $V(p)$ of possible worlds.
  \end{enumerate}
  When $Rww'$ holds, we say that $w'$ is \emph{accessible
    from}~$w$. When $w \in V(p)$ we say $p$ is \emph{true at}~$w$.
\end{defn}

target:
\begin{defn}
  د بنسټيزې مودالي ژبې يو \emph{مدل} درې‌ګونې $\mModel{M}
  = \tuple{W, R, V}$ ده، چې په دې کښې
  \begin{enumerate}
  \item $W$ د «نړۍو» يو نا تش سټ دے،
  \item $R$ پر~$W$ د لاسرسي يوه دوه‌ځاييزه اړيکه ده، او
  \item $V$ داسې تابع ده چې هر !!{propositional
    variable}~$p$ ته د ممکنه نړۍو يو سټ $V(p)$ ټاکي۔
  \end{enumerate}
  که $Rww'$ وي، نو وايو چې $w'$ له~$w$ څخه \emph{ورته لاسرسے
    لري}۔ که $w \in V(p)$ وي، نو وايو چې $p$ په~$w$ کښې
  \emph{رښتيا دے}۔
\end{defn}

