source:
\begin{prob}
  Let $\mModel{M} = \tuple{W, R, V}$ be a model, and suppose $w_1, w_2 \in
  W$ are such that:
  \begin{enumerate}
  \item $w_1 \in V(p)$ if and only if $w_2 \in V(p)$ (for every !!{propositional variable} $p$); and
  \item for all $w \in W$: $Rw_1w$ if and only if $Rw_2w$.
  \end{enumerate}
  Using induction on !!{formula}s, show that for all !!{formula}s $!A$:
  $\mSat{M}{!A}[w_1]$ if and only if $\mSat{M}{!A}[w_2]$.
\end{prob}

target:
\begin{prob}
  که $\mModel{M} = \tuple{W, R, V}$ يو مدل وي، او فرض کړئ $w_1, w_2 \in
  W$ داسې وي چې:
  \begin{enumerate}
  \item $w_1 \in V(p)$ هله او يوازې هله چې $w_2 \in V(p)$ وي (د هر !!{propositional variable} $p$ دپاره)؛ او
  \item د هر $w \in W$ دپاره: $Rw_1w$ هله او يوازې هله چې $Rw_2w$ وي۔
  \end{enumerate}
  پر !!{formula}s په استقرا سره وښيئ چې د ټولو !!{formula}s~$!A$ دپاره:
  $\mSat{M}{!A}[w_1]$ هله او يوازې هله چې $\mSat{M}{!A}[w_2]$ وي۔
\end{prob}

