source:
\begin{defn}
  !!^a{formula}~$!A$ is \emph{true in a model} $M = \tuple{W, R,
    V}$, written $\mSat{M}{!A}$, if and only if $\mSat{M}{!A}[w]$
  for every $w \in W$.
\end{defn}

target:
\begin{defn}
  !!^a{formula}~$!A$ په مدل $M = \tuple{W, R,
    V}$ کښې \emph{رښتيا} دے، او دا په $\mSat{M}{!A}$ ليکو، هله او
  يوازې هله چې د هر $w \in W$ دپاره $\mSat{M}{!A}[w]$ وي۔
\end{defn}

source:
\begin{prop}\ollabel{prop:truthfacts}
  \begin{enumerate}
  \item If $\mSat{M}{!A}$ then $\mSat/{M}{\lnot !A}$, but \emph{not}
    vice-versa.
  \item If $\mSat{M}{!A \lif !B}$ then $\mSat{M}{!A}$ only if
    $\mSat{M}{!B}$, but \emph{not} vice-versa.
  \end{enumerate}
\end{prop}

target:
\begin{prop}\ollabel{prop:truthfacts}
  \begin{enumerate}
  \item که $\mSat{M}{!A}$ وي، نو $\mSat/{M}{\lnot !A}$ وي؛ خو سرچپه
    نتيجه يې \emph{نۀ} سمېږي۔
  \item که $\mSat{M}{!A \lif !B}$ وي، نو $\mSat{M}{!A}$ يوازې هله
    چې $\mSat{M}{!B}$ وي؛ خو سرچپه نتيجه يې \emph{نۀ} سمېږي۔
  \end{enumerate}
\end{prop}

source:
\begin{proof}
  \begin{enumerate}
  \item If $\mSat{M}{!A}$ then $!A$ is true at all worlds in $W$, and
    since $W \neq \emptyset$, it can't be that $\mSat{M}{\lnot!A}$, or
    else $!A$ would have to be both true and false at some
    world.

target:
\begin{proof}
  \begin{enumerate}
  \item که $\mSat{M}{!A}$ وي، نو $!A$ د~$W$ په ټولو نړۍو کښې رښتيا
    دے۔ څرنګه چې $W \neq \emptyset$ دے، $\mSat{M}{\lnot!A}$ نۀ شي
    کېدے؛ ګنې $!A$ به لږ تر لږه په يوه نړۍ کښې هم رښتيا او هم نارښتيا
    وي۔

source:
\begin{prob}
  Consider the following model $\mModel{M}$ for the language
  comprising $p_1$, $p_2$, $p_3$ as the only !!{propositional variable}s:
  \begin{center}
    \begin{tikzpicture}[modal]
      \node[world] (w1) [label={[align=right]left:\mTrue{p_1}\\\mFalse{p_2}\\\mFalse{p_3}}]
            {$w_1$} ; 
      \node[world] (w2) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mFalse{p_3}},
        below right=of w1]  {$w_2$}; 
      \node[world] (w3) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mTrue{p_3}},
        above right=of w2] {$w_3$};
      \draw[reflexive above] (w3) to (w3); 
      \draw[->] (w1) to (w2);
      \draw[->] (w2) to (w3);
      \draw[->] (w1) to (w3); 
    \end{tikzpicture}
  \end{center}
  Are the following !!{formula}s and schemas true in the model $\mModel{M}$,
  i.e., true at every world in $\mModel{M}$? Explain.
  \begin{enumerate}
  \item $p\lif \Diamond p$ (for $p$ atomic);
  \item $!A\lif \Diamond !A$ (for $!A$ arbitrary);
  \item $\Box p \lif p$ (for $p$ atomic);
  \item $\lnot p \lif \Diamond \Box p$ (for $p$ atomic);
  \item $\Diamond \Box !A$ (for $!A$ arbitrary);
  \item $\Box \Diamond p$ (for $p$ atomic). 
  \end{enumerate}
\end{prob}

target:
\begin{prob}
  لاندې مدل $\mModel{M}$ وڅېړئ؛ په ژبه کښې يوازې $p_1$، $p_2$،
  $p_3$ !!{propositional variable}s دي:
  \begin{center}
    \begin{tikzpicture}[modal]
      \node[world] (w1) [label={[align=right]left:\mTrue{p_1}\\\mFalse{p_2}\\\mFalse{p_3}}]
            {$w_1$} ; 
      \node[world] (w2) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mFalse{p_3}},
        below right=of w1]  {$w_2$}; 
      \node[world] (w3) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mTrue{p_3}},
        above right=of w2] {$w_3$};
      \draw[reflexive above] (w3) to (w3); 
      \draw[->] (w1) to (w2);
      \draw[->] (w2) to (w3);
      \draw[->] (w1) to (w3); 
    \end{tikzpicture}
  \end{center}
  له لاندې کوم !!{formula}s او قالبونه په مدل $\mModel{M}$ کښې رښتيا
  دي، يعنې د $\mModel{M}$ په هره نړۍ کښې رښتيا دي؟ دليل يې ورکړئ۔
  \begin{enumerate}
  \item $p\lif \Diamond p$ (چې $p$ اټومي وي)؛
  \item $!A\lif \Diamond !A$ (چې $!A$ هره جمله وي)؛
  \item $\Box p \lif p$ (چې $p$ اټومي وي)؛
  \item $\lnot p \lif \Diamond \Box p$ (چې $p$ اټومي وي)؛
  \item $\Diamond \Box !A$ (چې $!A$ هره جمله وي)؛
  \item $\Box \Diamond p$ (چې $p$ اټومي وي)۔
  \end{enumerate}
\end{prob}

\begin{defn}
  !!^a{formula}~$!A$ د مدلونو په ټولګي $\mClass{C}$ کښې \emph{معتبر}
  دے، که د~$\mClass{C}$ په هر مدل کښې رښتيا وي (يعنې د~$\mClass{C}$
  د هر مدل په هره نړۍ کښې رښتيا وي)۔ که $!A$ په~$\mClass{C}$ کښې
  معتبر وي، نو $\mClass{C} \Entails !A$ ليکو؛ او که $!A$ د
  \emph{ټولو} مدلونو په ټولګي کښې معتبر وي، نو $\Entails !A$ ليکو۔
\end{defn}

source:
\begin{prop}\ollabel{prop:subset-class}
