\begin{prop}\ollabel{prop:relation-facts}
  Let $R$ be a binary relation on a set $W$; then:
  \begin{enumerate}
  \item If $R$ is reflexive, then it is serial.
  \item If $R$ is symmetric, then it is transitive if and only if it
    is euclidean.
  \item If $R$ is symmetric or euclidean then it is weakly directed
    (it has the ``diamond property'').
  \item If $R$ is euclidean then it is weakly connected.
  \item If $R$ is functional then it is serial.  
  \end{enumerate}
\end{prop}

target:
\begin{prop}\ollabel{prop:relation-facts}
  فرض کړئ $R$ پر يوه سټ $W$ دوه‌ځاييزه اړيکه ده؛ بيا:
  \begin{enumerate}
  \item که $R$ انعکاسي وي، نو مسلسل هم ده۔
  \item که $R$ متناظره وي، نو هله او يوازې هله انتقالي ده چې
    اقليدسي وي۔
  \item که $R$ متناظره يا اقليدسي وي، نو کمزورې هم‌لوري ده
    («الماسي خاصيت» لري)۔
  \item که $R$ اقليدسي وي، نو کمزورې تړلې ده۔
  \item که $R$ تابعي وي، نو مسلسل ده۔  
  \end{enumerate}
\end{prop}

