\begin{defn}
The rule of \emph{modus ponens} is the inference schema
\begin{prooftree}
\AxiomC{$!A$}
\AxiomC{$!A \lif !B$}
\RightLabel{\MP}
\BinaryInfC{$!B$}
\end{prooftree}
We say !!a{formula}~$!B$ \emph{follows from}~!!{formula}s $!A$, $!C$
by modus ponens iff $!C \ident !A \lif !B$.
\end{defn}

target:
\begin{defn}
د \emph{مودوس پوننس} قاعده دا استنتاجي طرحه ده:
\begin{prooftree}
\AxiomC{$!A$}
\AxiomC{$!A \lif !B$}
\RightLabel{\MP}
\BinaryInfC{$!B$}
\end{prooftree}
وايو چې !!a{formula}~$!B$ د مودوس پوننس له مخې
له !!{formula}s $!A$، $!C$ څخه \emph{راځي} هله
او يوازې هله چې $!C \ident !A \lif !B$ وي۔
\end{defn}

source:
\begin{defn}
The rule of \emph{necessitation} is the inference schema
\begin{prooftree}
\AxiomC{$!A$}
\RightLabel{\Nec}
\UnaryInfC{$\Box !A$}
\end{prooftree}
We say the !!{formula}~$!B$ follows from the !!{formula}s $!A$ by
necessitation iff $!B \ident \Box !A$.
\end{defn}

target:
\begin{defn}
د \emph{لزوم ورکولو} قاعده دا استنتاجي طرحه ده:
\begin{prooftree}
\AxiomC{$!A$}
\RightLabel{\Nec}
\UnaryInfC{$\Box !A$}
\end{prooftree}
وايو چې !!{formula}~$!B$ د لزوم ورکولو له مخې
له !!{formula}s $!A$ څخه راځي هله او يوازې هله
چې $!B \ident \Box !A$ وي۔
\end{defn}

\begin{defn}
د بديهي اصلونو له سټ~$\Sigma$ څخه يو \emph{!!{derivation}}
د !!{formula}s $!B_1$، $!B_2$، \dots، $!B_n$ داسې لړۍ
ده چې هر~$!B_i$ ئې يا
\begin{enumerate}
\item د يوې تاوتولوژۍ د ځايناستۍ مثال وي، يا
\item په~$\Sigma$ کښې د !!a{formula} د ځايناستۍ مثال وي، يا
\item له دوو !!{formula}s $!B_j$، $!B_k$ څخه، چې $j$، $k < i$ وي،
  د مودوس پوننس له مخې راځي، يا
\item له !!a{formula}~$!B_j$ څخه، چې $j < i$ وي،
  د لزوم ورکولو له مخې راځي۔
\end{enumerate}
که داسې !!a{derivation} وي چې $!B_n \ident !A$، نو وايو
چې~$!A$ \emph{له~$\Sigma$ څخه !!{derivable}} دے؛ په نښو
$\Sigma \Proves !A$۔
\end{defn}

source:
With this definition, it will turn out that the set of !!{derivable}
formulas forms a normal modal logic, and that any !!{derivable}
!!{formula} is true in every model in which every axiom is true. This
property of !!{derivation}s is called \emph{soundness}. The converse,
\emph{completeness}, is harder to prove.

\begin{defn}
  A \emph{modal logic} is a set~$\Sigma$ of modal !!{formula}s which
  \begin{enumerate}
  \item contains all tautologies, and
  \item is closed under substitution, i.e., if $!A \in \Sigma$, and
    $!D_1$, \dots, $!D_n$ are !!{formula}s, then
    \[
    \SSubst{!A}{\subst{!D_1}{p_1}, \dots, \subst{!D_n}{p_n}} \in \Sigma,
    \]
    \item is closed under \emph{modus ponens}, i.e., if $!A$ and $!A
      \lif !B \in \Sigma$, then $!B \in \Sigma$.
  \end{enumerate}
\end{defn}

\begin{defn}
  A modal logic $\Sigma$ is \emph{normal} if it contains
  \begin{align*}
    \tag{\Ax{K}} & \Box(p \lif q) \lif (\Box p \lif \Box q),
    \iftag{prvDiamond}{\\
      \tag{\Dual} & \Diamond p \liff \lnot\Box\lnot p}{}
  \end{align*}
  and is closed under \emph{necessitation}, i.e., if $!A \in
  \Sigma$, then $\Box !A \in \Sigma$.
\end{defn}

target:
\begin{defn}
  مودالي منطق~$\Sigma$ \emph{عادي} دے، که دا ولري:
  \begin{align*}
    \tag{\Ax{K}} & \Box(p \lif q) \lif (\Box p \lif \Box q),
    \iftag{prvDiamond}{\\
      \tag{\Dual} & \Diamond p \liff \lnot\Box\lnot p}{}
  \end{align*}
  او د \emph{لزوم ورکولو} لاندې تړلے وي، يعنې که $!A \in
  \Sigma$ وي، نو $\Box !A \in \Sigma$ وي۔
\end{defn}

source:
\begin{prop}\ollabel{prop:rk}
  Every normal modal logic is closed under rule \RK,
  \begin{prooftree}
    \AxiomC{$!A_1 \lif (!A_2 \lif \cdots (!A_{n-1} \lif !A_n)\cdots)$}
    \RightLabel{\RK}
    \UnaryInfC{$\Box!A_1 \lif (\Box!A_2 \lif \cdots (\Box!A_{n-1}
      \lif \Box!A_n)\cdots).$}
  \end{prooftree}
\end{prop}

target:
\begin{prop}\ollabel{prop:rk}
  هر عادي مودالي منطق د~\RK قاعدې لاندې تړلے دے:
  \begin{prooftree}
    \AxiomC{$!A_1 \lif (!A_2 \lif \cdots (!A_{n-1} \lif !A_n)\cdots)$}
    \RightLabel{\RK}
    \UnaryInfC{$\Box!A_1 \lif (\Box!A_2 \lif \cdots (\Box!A_{n-1}
      \lif \Box!A_n)\cdots).$}
  \end{prooftree}
\end{prop}

source:
\begin{proof}
  By induction on~$n$: If $n = 1$, then the rule is just \Nec, and
  every normal modal logic is closed under \Nec.

  Assume
  \begin{align*}
  & !A_1 \lif (!A_2 \lif \cdots (!A_{n-1} \lif !A_n)\cdots) \in \Sigma
  \intertext{By the induction hypothesis, we have}
  & \Box!A_1 \lif (\Box!A_2 \lif \cdots \Box(!A_{n-1} \lif !A_n)\cdots)
  \in \Sigma
  \intertext{Since $\Sigma$ is a normal modal logic, it contains all
    instances of~$\Ax{K}$, in particular}
  & \Box(!A_{n-1} \lif !A_n) \lif (\Box!A_{n-1} \lif \Box!A_n) \in \Sigma
  \intertext{Using modus ponens and suitable tautological instances we get}
  & \Box!A_1 \lif (\Box!A_2 \lif \cdots (\Box!A_{n-1}
  \lif \Box!A_n)\cdots) \in \Sigma. 
  \end{align*}
\end{proof}

target:
  فرض کړئ
  \begin{align*}
  & !A_1 \lif (!A_2 \lif \cdots (!A_{n-1} \lif !A_n)\cdots) \in \Sigma
  \intertext{د استقرا د فرض له مخې لرو:}
  & \Box!A_1 \lif (\Box!A_2 \lif \cdots \Box(!A_{n-1} \lif !A_n)\cdots)
  \in \Sigma
  \intertext{څرنګه چې $\Sigma$ عادي مودالي منطق دے، د~$\Ax{K}$
    ټول مثالونه لري، په ځانګړې توګه:}
  & \Box(!A_{n-1} \lif !A_n) \lif (\Box!A_{n-1} \lif \Box!A_n) \in \Sigma
  \intertext{د مودوس پوننس او د تاوتولوژۍ د مناسبو مثالونو له مخې ترلاسه کوو:}
  & \Box!A_1 \lif (\Box!A_2 \lif \cdots (\Box!A_{n-1}
  \lif \Box!A_n)\cdots) \in \Sigma. 
  \end{align*}
\end{proof}

