\begin{defn}
  A set $\Gamma$ is \emph{consistent} relatively to a system~$\Sigma$
  or, as we will say, $\Sigma$-consistent, if and only if $\Gamma
  \Proves/[\Sigma] \lfalse$.
\end{defn}

target:
\begin{defn}
  يو سټ~$\Gamma$ د نظام~$\Sigma$ په نسبت \emph{سازګار}، يا په لنډه
  «$\Sigma$-سازګار»، هله او يوازې هله وي چې $\Gamma
  \Proves/[\Sigma] \lfalse$.
\end{defn}

source:
\begin{prop}\ollabel{prop:consistencyfacts}
  Let $\Gamma$ be a set of !!{formula}s. Then:
  \begin{enumerate}
  \item $\Gamma$ is $\Sigma$-consistent if and only if there is
    some !!{formula}~$!A$ such that $\Gamma \Proves/[\Sigma]
    !A$.
  \item \ollabel{prop:consistencyfacts-b}%
    $\Gamma \Proves[\Sigma] !A$ if and only if $\Gamma \cup \{
    \lnot!A \}$ is not $\Sigma$-consistent.
  \item \ollabel{prop:consistencyfacts-c}%
    If $\Gamma$ is $\Sigma$-consistent, then for any !!{formula}
    $!A$, either $\Gamma \cup \{ !A \}$ is
    $\Sigma$-consistent or $\Gamma \cup \{ \lnot!A \}$ is
    $\Sigma$-consistent.
  \end{enumerate}
\end{prop}

target:
\begin{prop}\ollabel{prop:consistencyfacts}
  $\Gamma$ دې د !!{formula}s يو سټ وي۔ بيا:
  \begin{enumerate}
  \item $\Gamma$ هله او يوازې هله د~$\Sigma$ په نسبت سازګار وي چې
    داسې کوم !!{formula}~$!A$ وي چې $\Gamma \Proves/[\Sigma]
    !A$.
  \item \ollabel{prop:consistencyfacts-b}%
    $\Gamma \Proves[\Sigma] !A$ هله او يوازې هله وي چې $\Gamma \cup \{
    \lnot!A \}$ د~$\Sigma$ په نسبت سازګار نۀ وي۔
  \item \ollabel{prop:consistencyfacts-c}%
    که $\Gamma$ د~$\Sigma$ په نسبت سازګار وي، نو د هر !!{formula}
    $!A$ دپاره يا $\Gamma \cup \{ !A \}$ د~$\Sigma$ په نسبت
    سازګار وي يا $\Gamma \cup \{ \lnot!A \}$ د~$\Sigma$ په نسبت
    سازګار وي۔
  \end{enumerate}
\end{prop}

