\begin{defn}
  A system $\Sigma$ of modal logic is said to have the \emph{finite
    model property} if whenever !!a{formula}~$!A$ is true at a world
  in a model of $\Sigma$ then $!A$ is true at a world in a
  \emph{finite} model of~$\Sigma$.
\end{defn}

target:
\begin{defn}
  د مودالي منطق يو نظام~$\Sigma$ د \emph{متناهي
    مدل خاصيت} لري که هرکله چې کوم !!a{formula}~$!A$ د~$\Sigma$
  په يوه مدل کښې په يوه نړۍ رښتينے وي، نو $!A$ د~$\Sigma$ په
  يوه \emph{متناهي} مدل کښې هم په يوه نړۍ رښتينے وي۔
\end{defn}

