\begin{thm}\ollabel{thm:modal-closed-filt}
  Let $\Gamma$ be modally closed, $\mModel{M}=\tuple{W,R,V}$, and
  $\mModel{M^*} = \tuple{W^*,R^*,V^*}$ be a coarsest filtration of
  $\mModel{M}$.
  \begin{enumerate}
  \item If $\mModel{M}$ is symmetric, so is $\mModel{M^*}$.
  \item If $\mModel{M}$ is transitive, so is $\mModel{M^*}$.
  \item If $\mModel{M}$ is euclidean, so is $\mModel{M^*}$.
  \end{enumerate}
\end{thm}

target:
\begin{thm}\ollabel{thm:modal-closed-filt}
  فرض کړئ $\Gamma$ مودالي تړلے وي،
  $\mModel{M}=\tuple{W,R,V}$ وي، او
  $\mModel{M^*} = \tuple{W^*,R^*,V^*}$ د
  $\mModel{M}$ تر ټولو غټ فلټريشن وي۔
  \begin{enumerate}
  \item که $\mModel{M}$ متناظر وي، $\mModel{M^*}$ هم متناظر دے۔
  \item که $\mModel{M}$ متعدي وي، $\mModel{M^*}$ هم متعدي دے۔
  \item که $\mModel{M}$ اقليدسي وي، $\mModel{M^*}$ هم اقليدسي دے۔
  \end{enumerate}
\end{thm}

