\begin{defn}
  A \emph{model} for temporal language is a triple
  $\mModel{M} = \tuple{T, \prec, V}$, where
  \begin{enumerate}
  \item $T$ is a nonempty set, interpreted as points in time.
  \item $\prec$ is a binary relation on $T$.
  \item $V$ is a function assigning to each !!{propositional
    variable}~$p$ a set $V(p)$ of points in time.
  \end{enumerate}
  When $t \prec t'$ holds, we say that $t$ \emph{precedes}~$t'$. 
  When $t \in V(p)$ we say $p$ is \emph{true at}~$t$.
\end{defn}

target:
\begin{defn}
  د زماني ژبې يو \emph{مدل} درې‌ګونې
  $\mModel{M} = \tuple{T, \prec, V}$ ده، چې په دې کښې
  \begin{enumerate}
  \item $T$ يو نا تش سټ دے، چې د وخت د ټکو په توګه تفسيرېږي۔
  \item $\prec$ پر~$T$ يوه دوه‌ځاييزه اړيکه ده۔
  \item $V$ داسې تابع ده چې هر !!{propositional
    variable}~$p$ ته د وخت د ټکو يو سټ $V(p)$ ټاکي۔
  \end{enumerate}
  که $t \prec t'$ وي، نو وايو چې $t$ له~$t'$ څخه \emph{مخکښې راځي}۔
  که $t \in V(p)$ وي، نو وايو چې $p$ په~$t$ کښې \emph{رښتيا دے}۔
\end{defn}

