\begin{defn}\ollabel{defn:since-until}
  \emph{Truth of !!a{formula}~$!A$ at~$t$} in a~$\mModel M$:
  \begin{enumerate}
  \item\ollabel{defn:sub:mmodels-since} \indcase{!A}{\Since  !B
    !C}{$\mSat{M}{\indfrm}[t]$ iff $\mSat{M}{!B}[t']$ for some $t' \in
    T$ with $t' \prec t$, and for all $s$ with $t' \prec s \prec t$,
    $\mSat{M}{!C}[s]$}
   \item\ollabel{defn:sub:mmodels-until} \indcase{!A}{\Until !B
    !C}{$\mSat{M}{\indfrm}[t]$ iff $\mSat{M}{!B}[t']$ for some $t' \in
    T$ with $t \prec t'$, and for all $s$ with $t \prec s \prec t'$,
    $\mSat{M}{!C}[s]$}
  \end{enumerate} 
\end{defn}

target:
\begin{defn}\ollabel{defn:since-until}
  په~$\mModel M$ کښې د~$t$ په حالت کښې \emph{د !!a{formula}~$!A$ رښتياوالی}:
  \begin{enumerate}
  \item\ollabel{defn:sub:mmodels-since} \indcase{!A}{\Since  !B
    !C}{$\mSat{M}{\indfrm}[t]$ هله او يوازې هله چې د کوم $t' \in
    T$ دپاره $t' \prec t$ او $\mSat{M}{!B}[t']$ وي، او د هر هغه
    $s$ دپاره چې $t' \prec s \prec t$ وي، $\mSat{M}{!C}[s]$ وي}
   \item\ollabel{defn:sub:mmodels-until} \indcase{!A}{\Until !B
    !C}{$\mSat{M}{\indfrm}[t]$ هله او يوازې هله چې د کوم $t' \in
    T$ دپاره $t \prec t'$ او $\mSat{M}{!B}[t']$ وي، او د هر هغه
    $s$ دپاره چې $t \prec s \prec t'$ وي، $\mSat{M}{!C}[s]$ وي}
  \end{enumerate}
\end{defn}

source:
\begin{defn}\ollabel{defn:phmodels}
  \emph{Truth of !!a{formula}~$!A$ at~$t, \sigma$} in~$\mModel M$, in symbols:
  $\mSat{M}{!A}[t, \sigma]$:
  \begin{enumerate}
  \item\ollabel{defn:sub:phmodels-f} \indcase{!A}{\Ftemp
    !B}{$\mSat{M}{\indfrm}[t, \sigma]$ iff $\mSat{M}{!B}[t', \sigma]$
    for some $t' \in T$ such that $t \prec_\sigma t'$.}
  \item\ollabel{defn:sub:phmodels-diamond} \indcase{!A}{\Diamond
    !B}{$\mSat{M}{\indfrm}[t, \sigma]$ iff $\mSat{M}{!B}[t, \sigma']$
    for some $\sigma' \in C$ in which $t$ occurs.}
  \end{enumerate} 
\end{defn}

target:
\begin{defn}\ollabel{defn:phmodels}
  په~$\mModel M$ کښې په~$t, \sigma$ باندې \emph{د !!a{formula}~$!A$
  رښتياوالے}، چې په نښو کښې ئې $\mSat{M}{!A}[t, \sigma]$ ليکو:
  \begin{enumerate}
  \item\ollabel{defn:sub:phmodels-f} \indcase{!A}{\Ftemp
    !B}{$\mSat{M}{\indfrm}[t, \sigma]$ هله او يوازې هله چې د کوم
    $t' \in T$ دپاره $t \prec_\sigma t'$ او
    $\mSat{M}{!B}[t', \sigma]$ وي۔}
  \item\ollabel{defn:sub:phmodels-diamond} \indcase{!A}{\Diamond
    !B}{$\mSat{M}{\indfrm}[t, \sigma]$ هله او يوازې هله چې د
    کومې $\sigma' \in C$ دپاره چې $t$ پکښې راځي،
    $\mSat{M}{!B}[t, \sigma']$ وي۔}
  \end{enumerate}
\end{defn}

