\begin{defn}
  While the $\Knows$ operator is intended to symbolize individual
  knowledge, $\EKnows$, often read as ``everybody knows,'' symbolizes
  group knowledge. Where $G' \subseteq G$, we define $\EKnows_{G'} !A$
 as an abbreviation for \[\bigwedge_{b \in G'} \Knows_b !A.\]
\end{defn}

target:
\begin{defn}
  د $\Knows$ عامل د يوه کس د پوهې د ښودلو لپاره دے؛ $\EKnows$،
  چې ډېر ځله «هر څوک پوهېږي» لوستل کېږي، د ډلې د هر غړي پوهه ښيي۔
  که $G' \subseteq G$ وي، نو $\EKnows_{G'} !A$ د
  \[\bigwedge_{b \in G'} \Knows_b !A.\] لنډه نښه تعريفوو۔
\end{defn}

