source:
Axiomatic !!{derivation}s for intuitionistic propositional logic are
the conceptually simplest, and historically first, !!{derivation}
systems. They work just as in classical propositional logic.

target:
\begin{defn}[!!^{derivability}]
!!^a{formula}~$!A$ له $\Gamma$ څخه هله \emph{!!{derivable}}
ګڼل کېږي، او دا په $\Gamma \Proves !A$ ليکو، چې له
$\Gamma$ څخه داسې !!a{derivation} وي چې په $!A$ پاے ته رسېږي۔
\end{defn}

source:
\begin{defn}[Theorems]
!!^a{formula}~$!A$ is a \emph{theorem} if there is !!a{derivation}
of~$!A$ from the empty set.  We write $\Proves !A$ if $!A$ is a
theorem and $\Proves/ !A$ if it is not.
\end{defn}

\begin{prop}
  If $\Gamma \Proves !A$ in the axiomatic !!{derivation} system for
  intuitionistic logic, $\Gamma \Proves !A$ also in
  classical logic. In particular, if $!A$ is an intuitionistic
  theorem, it is also a classical theorem.
\end{prop}

target:
\begin{prop}
  که د شهودي منطق په بديهي !!{derivation} نظام کښې
  $\Gamma \Proves !A$ وي، نو په کلاسيک منطق کښې هم
  $\Gamma \Proves !A$ وي۔ په تېره بيا، که $!A$ شهودي قضيه وي،
  نو کلاسيکه قضيه هم ده۔
\end{prop}

source:
\begin{proof}
  Every intuitionistic axiom is also a classical axiom, so every
  !!{derivation} in intuitionistic logic is also !!a{derivation} in
  classical logic.
\end{proof}

target:
\begin{proof}
  هر شهودي بديهي اصل هم کلاسيک بديهي اصل دے؛ نو په شهودي منطق کښې
  هر !!{derivation} په کلاسيک منطق کښې هم !!a{derivation} دے۔
\end{proof}

