source:
\begin{defn}
  !!^a{relational model} for intuitionistic propositional logic is a
  triple $\mModel{M} = \tuple{W, R, V}$, where
  \begin{enumerate}
  \item $W$ is a non-empty set,
  \item $R$ is a partial order (i.e., a reflexive, antisymmetric, and transitive binary relation) on~$W$, and
  \item $V$ is a function assigning to each !!{propositional
    variable}~$p$ a subset of~$W$, such that
  \item $V$ is monotone with respect to $R$, i.e., if $w
    \in V(p)$ and $Rww'$, then $w' \in V(p)$.
  \end{enumerate}
\end{defn}

target:
\begin{defn}
  د شهودي قضييز منطق !!^a{relational model} يوه درېګونې
  $\mModel{M} = \tuple{W, R, V}$ ده، چې پکې
  \begin{enumerate}
  \item $W$ يو ناتش سټ دے،
  \item $R$ پر~$W$ جزئي ترتيب دے (يعنې انعکاسي، ضد متقارن او
    متعدي دوه‌ځاييزه اړيکه)، او
  \item $V$ داسې تابع ده چې هر !!{propositional
    variable}~$p$ ته د~$W$ يو فرعي سټ ټاکي،
  \item $V$ د $R$ له مخې يورخيزه زياتېدونکې وي، يعنې که $w
    \in V(p)$ او $Rww'$ وي، نو $w' \in V(p)$ وي۔
  \end{enumerate}
\end{defn}

