\begin{prop}
  Suppose for every model~$\mModel{M}$ such that $\mSat{M}{\Gamma}$,
  $\mSat{M}{!A}$. Then $\Gamma \Entails !A$.
\end{prop}

target:
\begin{prop}
  فرض کړئ چې د هر داسې مدل~$\mModel{M}$ لپاره چې
  $\mSat{M}{\Gamma}$ وي، $\mSat{M}{!A}$ هم وي۔ نو
  $\Gamma \Entails !A$ دے۔
\end{prop}

source:
\begin{proof}
  Suppose that $\mSat{M}{\Gamma}[w]$. By the \olref{prop:restrict}
  applied to every~$!B \in \Gamma$, we have $\mSat{M_w}{\Gamma}$. By
  the assumption, we have $\mSat{M_w}{!A}$. By \olref{prop:restrict}
  again, we get $\mSat{M}{!A}[w]$.
\end{proof}

\begin{defn}
  Let $X$ be a set. A \emph{topology on~$X$} is a set $\Top{O}
  \subseteq \Pow{X}$ that satisfies the properties below. The
  !!{element}s of~$\Top{O}$ are called the \emph{open sets} of the
  topology. The set $X$ together with $\Top{O}$ is called a
  \emph{topological space}.
  \begin{enumerate}
  \item The empty set and the entire space are open: $\emptyset$, $X \in
    \Top{O}$.
  \item Open sets are closed under finite intersections: if $U$, $V \in
    \Top{O}$ then $U \cap V \in \Top{O}$
  \item Open sets are closed under arbitrary unions: if $U_i \in
    \Top{O}$ for all $i \in I$, then $\bigcup \Setabs{U_i}{i \in
      I} \in \Top{O}$.
  \end{enumerate}
\end{defn}

target:
\begin{defn}
  فرض کړئ $X$ يو سټ دے۔ پر~$X$ \emph{توپولوژي} داسې سټ
  $\Top{O} \subseteq \Pow{X}$ دے چې لاندې خاصيتونه پوره کوي۔
  د~$\Top{O}$ !!{element}s د توپولوژۍ \emph{پرانيستي سټونه}
  بلل کېږي۔ سټ $X$ له $\Top{O}$ سره په ګډه \emph{توپولوژيکي فضا}
  بلل کېږي۔
  \begin{enumerate}
  \item تش سټ او ټوله فضا پرانيستي دي: $\emptyset$، $X \in
    \Top{O}$۔
  \item پرانيستي سټونه د متناهي تقاطع له مخې تړلي دي: که $U$، $V \in
    \Top{O}$ وي، نو $U \cap V \in \Top{O}$۔
  \item پرانيستي سټونه د هرې اجتماع له مخې تړلي دي: که د هر $i \in I$
    لپاره $U_i \in \Top{O}$ وي، نو $\bigcup \Setabs{U_i}{i \in
      I} \in \Top{O}$۔
  \end{enumerate}
\end{defn}

