  وي۔ ثبوت له~$\Gamma$ څخه د~$!A$ پر !!{derivation} استقرا ده۔

source:
\begin{prob}
  Complete the proof of \olref[int][sc][snd]{thm:soundness}. For the
  cases for $\Intro\lnot$ and $\Elim\lnot$, use the definition of
  $\mSat{M}{\lnot !A}[w]$ in \olref[int][sem][rel]{defn:true-at-w}, i.e.,
  don't treat $\lnot !A$ as defined by $!A \lif \lfalse$.
\end{prob}

\begin{prob}
  Show that the following !!{formula}s are not !!{derivable} in
  intuitionistic logic:
  \begin{enumerate}
    \item $(!A \lif !B) \lor (!B \lif !A)$
    \item $(\lnot\lnot !A \lif !A) \lif (!A \lor \lnot !A)$
    \item $(!A \lif !B \lor !C) \lif \bigl((!A \lif !B)\lor(!A \lif !C)\bigr)$
  \end{enumerate}
\end{prob}

target:
\begin{prob}
  وښيئ چې لاندې !!{formula}s په شهودي منطق کښې !!{derivable} نۀ دي:
  \begin{enumerate}
    \item $(!A \lif !B) \lor (!B \lif !A)$
    \item $(\lnot\lnot !A \lif !A) \lif (!A \lor \lnot !A)$
    \item $(!A \lif !B \lor !C) \lif \bigl((!A \lif !B)\lor(!A \lif !C)\bigr)$
  \end{enumerate}
\end{prob}

source:
\begin{defn}\ollabel{defn:prime}
  A set of !!{formula}s~$\Gamma$ is \emph{prime} iff 
  \begin{enumerate}
  \item\ollabel{defn:prime1} $\Gamma$ is consistent, i.e., $\Gamma \Proves/ \lfalse$;
  \item\ollabel{defn:prime2} if $\Gamma \Proves !A$ then $!A \in \Gamma$; and
  \item\ollabel{defn:prime3} if $!A \lor !B \in \Gamma$ then $!A \in
    \Gamma$ or $!B \in \Gamma$.
  \end{enumerate}
\end{defn}

target:
\begin{defn}\ollabel{defn:prime}
  د !!{formula}s سټ~$\Gamma$ هله او يوازې هله \emph{اولنی} دے چې
  \begin{enumerate}
  \item\ollabel{defn:prime1} $\Gamma$ سازګار وي، يعنې $\Gamma \Proves/ \lfalse$؛
  \item\ollabel{defn:prime2} که $\Gamma \Proves !A$ وي، نو $!A \in \Gamma$ وي؛ او
  \item\ollabel{defn:prime3} که $!A \lor !B \in \Gamma$ وي، نو $!A \in
    \Gamma$ يا $!B \in \Gamma$ وي۔
  \end{enumerate}
\end{defn}

source:
Define $\Gamma_0 = \Gamma$ and
\[
\Gamma_{n+1} = \begin{cases}
  \Gamma_n \cup \{!B_{i(n)}\} &
  \text{if $\Gamma_n \cup \{!B_{i(n)}\} \Proves/ !A$} \\
  \Gamma_n \cup \{!C_{i(n)}\} & \text{otherwise}
  \end{cases}
\]
If $i(n)$ is undefined, i.e., whenever $\Gamma_n \Proves !B \lor !C$,
either $!B \in \Gamma_n$ or $!C \in \Gamma_n$, we let $\Gamma_{n+1}
= \Gamma_n$.  Now let $\Gamma^* = \bigcup_{n=0}^\infty \Gamma_n$

target:
$\Gamma_0 = \Gamma$ او
\[
\Gamma_{n+1} = \begin{cases}
  \Gamma_n \cup \{!B_{i(n)}\} &
  \text{که $\Gamma_n \cup \{!B_{i(n)}\} \Proves/ !A$ وي} \\
  \Gamma_n \cup \{!C_{i(n)}\} & \text{که داسې نۀ وي}
  \end{cases}
\]
تعريف کړئ۔ که $i(n)$ نۀ وي ټاکلے، يعنې هر کله چې
$\Gamma_n \Proves !B \lor !C$ وي، نو يا $!B \in \Gamma_n$
يا $!C \in \Gamma_n$ وي، $\Gamma_{n+1}
= \Gamma_n$ ږدو۔ اوس $\Gamma^* = \bigcup_{n=0}^\infty \Gamma_n$
ږدو۔

