source:
\begin{defn}\ollabel{defn:canonical-model}
  Suppose $\Delta$ is prime.  Then the \emph{canonical model} $\mModel{M(\Delta)}$ for
  $\Delta$ is defined by:
  \begin{enumerate}
  \item $W = \Nat^*$, the set of finite sequences of natural numbers.
  \item $R$ is the partial order according to which $R\sigma\sigma'$
    iff $\sigma$ is an initial segment of~$\sigma'$ (i.e., $\sigma' =
    \sigma \concat \sigma''$ for some sequence~$\sigma''$).
  \item $V(p) = \Setabs{\sigma}{p \in \Delta(\sigma)}$.
  \end{enumerate}
\end{defn}

target:
\begin{defn}\ollabel{defn:canonical-model}
  فرض کړئ $\Delta$ اولنی دے۔ نو د~$\Delta$ دپاره
  \emph{کانوني مدل} $\mModel{M(\Delta)}$ داسې تعريفېږي:
  \begin{enumerate}
  \item $W = \Nat^*$، د طبيعي عددونو د متناهي لړيو سټ۔
  \item $R$ داسې جزئي ترتيب دے چې $R\sigma\sigma'$ هله او
    يوازې هله وي چې $\sigma$ د~$\sigma'$ لومړنۍ برخه وي
    (يعنې د کومې لړۍ~$\sigma''$ دپاره $\sigma' =
    \sigma \concat \sigma''$ وي)۔
  \item $V(p) = \Setabs{\sigma}{p \in \Delta(\sigma)}$۔
  \end{enumerate}
\end{defn}

source:
\begin{lem}\ollabel{lem:truth}
  If $\Delta$ is prime, then $\mSat{M(\Delta)}{!A}[\sigma]$ iff
  $\Delta(\sigma) \Proves !A$.
\end{lem}

target:
\begin{lem}\ollabel{lem:truth}
  که $\Delta$ اولنی وي، نو $\mSat{M(\Delta)}{!A}[\sigma]$ هله
  او يوازې هله چې $\Delta(\sigma) \Proves !A$ وي۔
\end{lem}

source:
\begin{thm}\ollabel{thm:completeness}
  If $\Gamma \Entails !A$ then $\Gamma \Proves !A$.
\end{thm}

target:
\begin{thm}\ollabel{thm:completeness}
  که $\Gamma \Entails !A$ وي، نو $\Gamma \Proves !A$ وي۔
\end{thm}

source:
\begin{prob}
  Show that if $!A$ only contains !!{propositional variable}s, $\lor$,
  and~$\land$, then $\Entails/ !A$. Use this to conclude that $\lif$ is
  not definable in intuitionistic logic from $\lor$ and~$\land$. 
\end{prob}

target:
\begin{prob}
  وښيئ چې که $!A$ يوازې !!{propositional variable}s، $\lor$
  او~$\land$ ولري، نو $\Entails/ !A$ وي۔ له دې څخه نتيجه
  واخلئ چې $\lif$ په شهودي منطق کښې له $\lor$ او~$\land$
  څخه نۀ تعريفېږي۔
\end{prob}

source:
\begin{prob}
  By using the completeness theorem prove that if $\Proves !A \lor !B$ then
  $\Proves !A$ or $\Proves !B$. (Hint: Assume $\mSat/{M_1}{!A}$ and
  $\mSat/{M_2}{!B}$ and construct a new model $\mModel{M}$ such that
  $\mSat/{M}{!A \lor !B}$.)
\end{prob}

target:
\begin{prob}
  د بشپړتيا د قضيې په کارولو ثابت کړئ چې که $\Proves !A \lor !B$
  وي، نو $\Proves !A$ يا $\Proves !B$ وي۔ (لارښوونه: فرض
  کړئ $\mSat/{M_1}{!A}$ او $\mSat/{M_2}{!B}$ وي او داسې
  نوے مدل~$\mModel{M}$ جوړ کړئ چې $\mSat/{M}{!A \lor !B}$ وي۔)
\end{prob}

source:
\begin{prob} 
  Show that if $\mModel{M}$ is a relational model using a linear order then
  $\mSat{M}{(!A \lif !B)\lor(!B \lif !A)}$.
\end{prob}

target:
\begin{prob} 
  وښيئ چې که $\mModel{M}$ داسې اړيکيز مدل وي چې خطي ترتيب
  کاروي، نو $\mSat{M}{(!A \lif !B)\lor(!B \lif !A)}$ وي۔
\end{prob}

source:
\begin{thm}\ollabel{thm:decidability}
  If $\Entails/ !A$ then there is a finite model $\mSat/{M'}{!A}$.
\end{thm}

target:
\begin{thm}\ollabel{thm:decidability}
  که $\Entails/ !A$ وي، نو داسې متناهي مدل شته چې
  $\mSat/{M'}{!A}$ وي۔
\end{thm}

