\begin{lem}[in \emph{Grundgesetze}]\ollabel{lem:Fregeextensions}
$\forall F \forall a(a \in \fregeext{x}{F(x)} \liff Fa)$
\end{lem}

target:
\begin{lem}[په \emph{Grundgesetze} کښې]\ollabel{lem:Fregeextensions}
$\forall F \forall a(a \in \fregeext{x}{F(x)} \liff Fa)$
\end{lem}

source:
\begin{proof} 
Fix $F$ and $a$. Now $a \in \fregeext{x}{F(x)}$ iff $\exists G(\fregeext{x}{F(x)}
= \fregeext{x}{G(x)} \land Ga)$ (by the definition of membership) iff
$\exists G(\forall x(Fx \liff Gx) \land Ga)$ (by Basic Law V) iff $Fa$
(by elementary second-order logic).
\end{proof}

target:
\begin{proof} 
$F$ او $a$ ثابت ونيسئ۔ اوس $a \in \fregeext{x}{F(x)}$ که او يوازې که
$\exists G(\fregeext{x}{F(x)}
= \fregeext{x}{G(x)} \land Ga)$ (د غړيتوب د تعريف له مخې)، که او يوازې که
$\exists G(\forall x(Fx \liff Gx) \land Ga)$ (د پنځم بنسټيز قانون له مخې)، که او يوازې که $Fa$
(د دويمې درجې د بنسټيز منطق له مخې)۔
\end{proof}

source:
\begin{lem}[in \emph{Grundgesetze}.]
$\forall F \exists s \forall a (a \in s \liff Fa)$
\end{lem}

target:
\begin{lem}[په \emph{Grundgesetze} کښې۔]
$\forall F \exists s \forall a (a \in s \liff Fa)$
\end{lem}

source:
\begin{proof}
Fix $F$; now \olref{lem:Fregeextensions} yields $\forall a (a \in
\fregeext{x}{F(x)} \liff Fa)$; so $\exists s\forall a(a \in s \liff Fa)$ by
existential generalisation. The result follows since $F$ was
arbitrary.
\end{proof}

target:
\begin{proof}
$F$ ثابت ونيسئ؛ اوس \olref{lem:Fregeextensions} دا راکوي چې $\forall a (a \in
\fregeext{x}{F(x)} \liff Fa)$؛ نو د وجودي عمومي کولو له مخې $\exists s\forall a(a \in s \liff Fa)$۔
نتيجه ترې راځي، ځکه $F$ هر يو ټاکل کېدلے شو۔
\end{proof}

