\begin{defn}
For any ordinal $\alpha$, its \emph{successor} is $\ordsucc{\alpha}
=\alpha \cup \{\alpha\}$. We say that $\alpha$ is a \emph{successor}
ordinal if $\ordsucc{\beta} = \alpha$ for some ordinal~$\beta$. We
say that $\alpha$ is a \emph{limit} ordinal iff $\alpha$ is neither
empty nor a successor ordinal.
\end{defn}
\noindent
The following result shows that this is the right notion of
\emph{successor}:

target:
\begin{defn}
د هر ترتيبي عدد $\alpha$ \emph{تالي} $\ordsucc{\alpha}
=\alpha \cup \{\alpha\}$ دے. وايو چې $\alpha$ \emph{تالي} ترتيبي عدد دے،
که $\ordsucc{\beta} = \alpha$ د کوم ترتيبي عدد~$\beta$ دپاره وي.
وايو چې $\alpha$ \emph{حدي} ترتيبي عدد دے، که او يوازې که $\alpha$
نۀ تش وي او نۀ تالي ترتيبي عدد وي.
\end{defn}
\noindent
لاندې نتيجه ښيي چې دا د \emph{تالي} مناسب مفهوم دے:

source:
\begin{prop}
For any ordinal $\alpha$:
\begin{enumerate}
	\item $\alpha \in \ordsucc{\alpha}$;
	\item $\ordsucc{\alpha}$ is an ordinal;
	\item there is no ordinal $\beta$ such that $\alpha \in \beta \in
	\ordsucc{\alpha}$.
	\end{enumerate}
\end{prop}

target:
\begin{prop}
د هر ترتيبي عدد $\alpha$ دپاره:
\begin{enumerate}
	\item $\alpha \in \ordsucc{\alpha}$؛
	\item $\ordsucc{\alpha}$ ترتيبي عدد دے؛
	\item داسې ترتيبي عدد $\beta$ نشته چې $\alpha \in \beta \in
	\ordsucc{\alpha}$ وي.
	\end{enumerate}
\end{prop}

source:
\begin{thm}[Simple Transfinite Induction]\ollabel{simpletransrecursion}
Let $\phi(x)$ be a formula such that:
\begin{enumerate}
	\item $\phi(\emptyset)$; and
	\item for any ordinal $\alpha$, if $\phi(\alpha)$ then
	$\phi(\ordsucc{\alpha})$; and 
	\item if $\alpha$ is a limit ordinal and $(\forall \beta \in
	\alpha)\phi(\beta)$, then $\phi(\alpha)$.
\end{enumerate}
Then $\forall \alpha \phi(\alpha)$.
\end{thm}

target:
\begin{thm}[د نامتناهيت هاخوا ساده استقرا]\ollabel{simpletransrecursion}
فرض کړئ $\phi(x)$ داسې فارمول دے چې:
\begin{enumerate}
	\item $\phi(\emptyset)$؛ او
	\item د هر ترتيبي عدد $\alpha$ دپاره، که $\phi(\alpha)$ وي، نو
	$\phi(\ordsucc{\alpha})$ وي؛ او
	\item که $\alpha$ حدي ترتيبي عدد وي او $(\forall \beta \in
	\alpha)\phi(\beta)$ وي، نو $\phi(\alpha)$ وي.
\end{enumerate}
بيا $\forall \alpha \phi(\alpha)$ دے.
\end{thm}

source:
\begin{prop}
If $X$ is a set of ordinals, $\supstrict(X)$ is the least ordinal
greater than every ordinal in $X$.
\end{prop}

target:
\begin{prop}
که $X$ د ترتيبي عددونو سټ وي، نو $\supstrict(X)$ هغه تر ټولو کوچنے
ترتيبي عدد دے چې د $X$ له هر ترتيبي عدد څخه لوے وي.
\end{prop}

په معکوسه توګه، که $\alpha \in \supstrict(X)$ وي، نو $\alpha \in
\ordsucc{\beta} \in Y$ د کوم $\beta \in X$ دپاره دي، نو $\alpha \leq
\beta \in X$ دي. په دې توګه $\supstrict(X)$ د $X$ تر ټولو \emph{لږ}
اکيد پاسنے حد دے.
\end{proof}

