\begin{thm}[\emph{in $\ZF$}]
The following claims are equivalent:
\begin{enumerate}
	\item\ollabel{equivwo} The Axiom of Well-Ordering
	\item\ollabel{equivcompare} Either $\cardle{A}{B}$ or
	$\cardle{B}{A}$, for any sets $A$ and $B$
\end{enumerate}
\end{thm}

