source:
\begin{thm}
  With $n$ dice one can throw all $5n+1$ possible values between $n$
  and $6n$.
\end{thm}

target:
\begin{thm}
په $n$ نرد دانو ټول $5n+1$ ممکنه ارزښتونه غورځولاے شو،
د $n$ او $6n$ تر منځ۔
\end{thm}

source:
\begin{proof}
Let $P(n)$ be the claim: ``It is possible to throw any number between
$n$ and~$6n$ using $n$~dice.''  To use induction, we prove:
\begin{enumerate}
\item The \emph{induction basis} $P(1)$, i.e., with just one die,
  you can throw any number between $1$ and $6$.
\item The \emph{induction step}, for all $k$, if $P(k)$ then~$P(k+1)$.
\end{enumerate}

target:
\begin{proof}
$P(n)$ دې دا دعوه وي چې «د $n$ او~$6n$ تر منځ هر عدد
غورځول ممکن دي، په $n$~نرد دانو»۔ د استقرا د کارولو دپاره
دا ثابتوو:
\begin{enumerate}
\item \emph{د استقرا بنسټ} $P(1)$، يعنې په يوازې يوه دانه
  د $1$ او $6$ تر منځ هر عدد غورځولاے شئ۔
\item \emph{د استقرا ګام}، چې د ټولو $k$ دپاره، که $P(k)$
  وي نو~$P(k+1)$ هم وي۔
\end{enumerate}

