source:
\begin{defn}[Nice terms]
  The set of \emph{nice terms} is inductively defined as follows:
  \begin{enumerate}
  \item Any letter $\mathrm{a}$, $\mathrm{b}$, $\mathrm{c}$,
    $\mathrm{d}$ is a nice term.
  \item If $s_1$ and $s_2$ are nice terms, then so
    is $[s_1 \circ s_2]$.
  \item Nothing else is a nice term.
  \end{enumerate}
\end{defn}

target:
\begin{defn}[ښه‌جوړ ترمونه]
د \emph{ښه‌جوړو ترمونو} سټ په استقرايي ډول داسې تعريفېږي:
  \begin{enumerate}
  \item هر $\mathrm{a}$، $\mathrm{b}$، $\mathrm{c}$،
    $\mathrm{d}$ تورے يو ښه‌جوړ ترم دے۔
  \item که $s_1$ او $s_2$ ښه‌جوړ ترمونه وي، نو
    $[s_1 \circ s_2]$ هم ښه‌جوړ ترم دے۔
  \item نور هېڅ څه ښه‌جوړ ترم نۀ دي۔
  \end{enumerate}
\end{defn}

