source:
\begin{prob}
  Define the set of supernice terms by
  \begin{enumerate}
  \item Any letter $\mathrm{a}$, $\mathrm{b}$, $\mathrm{c}$,
    $\mathrm{d}$ is a supernice term.
  \item If $s$ is a supernice term, then so is $[s]$.
  \item If $s_1$ and $s_2$ are supernice terms, then so
    is $[s_1 \circ s_2]$.
  \item Nothing else is a supernice term.
  \end{enumerate}
  Show that the number of $[$ in a supernice term~$t$ of length~$n$ is
    $\le n/2 +1$.
\end{prob}

target:
\begin{prob}
د ډېرو ښه‌جوړو ترمونو سټ داسې تعريف کړئ:
  \begin{enumerate}
  \item هر $\mathrm{a}$، $\mathrm{b}$، $\mathrm{c}$،
    $\mathrm{d}$ تورے يو ډېر ښه‌جوړ ترم دے۔
  \item که $s$ ډېر ښه‌جوړ ترم وي، نو $[s]$ هم دے۔
  \item که $s_1$ او $s_2$ ډېر ښه‌جوړ ترمونه وي، نو
    $[s_1 \circ s_2]$ هم دے۔
  \item نور هېڅ څه ډېر ښه‌جوړ ترم نۀ دي۔
  \end{enumerate}
وښيئ چې د $[$ شمېر په ډېر ښه‌جوړ ترم~$t$ کښې، چې
اوږدوالے ئې~$n$ دے، $\le n/2 +1$ دے۔
\end{prob}

