يوازې يو تورے دے، يا په يکتا ډول ټاکل شوي
ښه‌جوړ ترمونه $s_1$، $s_2$ شته چې~$t =
  [s_1 \circ s_2]$۔
\end{prop}

source:
\begin{defn}
  \ollabel{defn:depth} The \emph{depth} of a nice term, $f(t)$, is
  defined inductively as follows:
  \[
  f(t) = \begin{cases}
    0 & \text{ if $t$ is a letter}\\
    \max(f(s_1), f(s_2)) + 1 & \text{ if $t = [s_1 \circ s_2]$.}
  \end{cases}
  \]
\end{defn}

target:
\begin{defn}
\ollabel{defn:depth} د يوه ښه‌جوړ ترم
\emph{ژوروالے}، $f(t)$، په استقرايي
ډول داسې تعريفېږي:
  \[
  f(t) = \begin{cases}
    0 & \text{ که $t$ يو تورے وي}\\
    \max(f(s_1), f(s_2)) + 1 & \text{ که $t = [s_1 \circ s_2]$ وي۔}
  \end{cases}
  \]
\end{defn}

