\begin{prop}
\ollabel{prop:mcs}
Suppose $\Gamma$ is maximally consistent. Then:
\begin{enumerate}
\item \ollabel{prop:mcs-prov-in} If $\Gamma \Proves !A$, then $!A \in
  \Gamma$.

target:
\begin{prop}
\ollabel{prop:mcs}
فرض کړئ چې $\Gamma$ اعظمي سازګار دے۔ نو:
\begin{enumerate}
\item \ollabel{prop:mcs-prov-in} که $\Gamma \Proves !A$ وي، نو $!A \in \Gamma$۔

source:
\tagitem{prvIf}{\ollabel{prop:mcs-if} $(!A \lif !B) \in \Gamma$ iff
  either $!A \notin \Gamma$ or $!B \in \Gamma$.}{}
\end{enumerate}
\end{prop}

target:
\tagitem{prvIf}{\ollabel{prop:mcs-if} $(!A \lif !B) \in \Gamma$ هله او يوازې هله چې يا $!A \notin \Gamma$ يا $!B \in \Gamma$۔}{}
