\begin{prop}[Monotonicity]
\ollabel{prop:monotonicity}
If $\Gamma \subseteq \Delta$ and $\Gamma \Proves !A$, then $\Delta
\Proves !A$.
\end{prop}

target:
\begin{prop}[يکنواختي]
\ollabel{prop:monotonicity}
که $\Gamma \subseteq \Delta$ او $\Gamma \Proves !A$ وي، نو
$\Delta \Proves !A$۔
\end{prop}

\begin{proof}
فرض کړئ $\Gamma \Proves !A$، يعنې يو متناهي
$\Gamma_0 \subseteq \Gamma$ شته چې
$\Gamma_0 \Sequent !A$ !!{derivable} دے۔ ځکه چې
$\Gamma \subseteq \Delta$، نو $\Gamma_0$ د~$\Delta$ هم يو متناهي
فرعي سټ دے۔ له دې امله د $\Gamma_0 \Sequent !A$ !!{derivation}
هم $\Delta \Proves !A$ ښيي۔
\end{proof}

source:
\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup \Delta \Proves
!B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

target:
\begin{prop}[انتقاليت]
\ollabel{prop:transitivity}
که $\Gamma \Proves !A$ او $\{!A\} \cup \Delta \Proves !B$ وي، نو
$\Gamma \cup \Delta \Proves !B$۔
\end{prop}

source:
\begin{proof}
If $\Gamma \Proves !A$, there is a finite $\Gamma_0 \subseteq \Gamma$
and !!a{derivation}~$\pi_0$ of $\Gamma_0 \Sequent !A$.  If $\{!A\}
\cup \Delta \Proves !B$, then for some finite subset $\Delta_0
\subseteq \Delta$, there is !!a{derivation}~$\pi_1$ of $!A, \Delta_0
\Sequent !B$. Consider the following !!{derivation}:
\begin{prooftree}
  \AxiomC{}
  \RightLabel{$\pi_0$}
  \Deduce$\Gamma_0 \fCenter !A$
  \AxiomC{}
  \RightLabel{$\pi_1$}
  \Deduce$!A, \Delta_0 \fCenter !B$
  \RightLabel{\Cut}
  \BinaryInf$\Gamma_0, \Delta_0 \fCenter !B$
\end{prooftree}
Since $\Gamma_0 \cup \Delta_0 \subseteq \Gamma \cup \Delta$, this
shows $\Gamma \cup \Delta \Proves !B$.
\end{proof}

target:
\begin{proof}
که $\Gamma \Proves !A$ وي، يو متناهي
$\Gamma_0 \subseteq \Gamma$ او د
$\Gamma_0 \Sequent !A$ !!a{derivation}~$\pi_0$ شته۔ که
$\{!A\} \cup \Delta \Proves !B$ وي، نو د کوم متناهي فرعي سټ
$\Delta_0 \subseteq \Delta$ دپاره د
$!A, \Delta_0 \Sequent !B$ !!a{derivation}~$\pi_1$ شته۔ لاندې
!!{derivation} وګورئ:
\begin{prooftree}
  \AxiomC{}
  \RightLabel{$\pi_0$}
  \Deduce$\Gamma_0 \fCenter !A$
  \AxiomC{}
  \RightLabel{$\pi_1$}
  \Deduce$!A, \Delta_0 \fCenter !B$
  \RightLabel{\Cut}
  \BinaryInf$\Gamma_0, \Delta_0 \fCenter !B$
\end{prooftree}
ځکه چې $\Gamma_0 \cup \Delta_0 \subseteq \Gamma \cup \Delta$، نو
دا $\Gamma \cup \Delta \Proves !B$ ښيي۔
\end{proof}

