\begin{defn}\label{defn:normal-modal-logic}
A modal logic~$\Log L$ is \emph{normal} iff 
\begin{enumerate}
\item it contains both
\begin{align}
\tag{K} \Box(p \lif q) & \lif (\Box p \lif \Box q) \\
\tag{Dual} \Diamond p & \liff \lnot \Box \lnot p
\end{align}
\item and it is closed under necessitation, i.e., whenever $!A \in
  \Log L$, then also $\Box !A \in \Log L$.
\end{enumerate}
\end{defn}

target:
\begin{defn}\label{defn:normal-modal-logic}
مودالي منطق~$\Log L$ هله او يوازې هله \emph{عادي} دے چې
\begin{enumerate}
\item دا دواړه ولري:
\begin{align}
\tag{K} \Box(p \lif q) & \lif (\Box p \lif \Box q) \\
\tag{Dual} \Diamond p & \liff \lnot \Box \lnot p
\end{align}
\item او د لزوم ورکولو لاندې تړلے وي؛ يعنې هر کله چې $!A \in
  \Log L$ وي، نو $\Box !A \in \Log L$ هم وي۔
\end{enumerate}
\end{defn}

